/* Vragenbank PA-toets, Wft Inkomen. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["inkomen"] = [
["Hoe lang moet een werkgever als hoofdregel het loon doorbetalen aan een zieke werknemer?", [["Maximaal 104 weken", "De loondoorbetalingsplicht bij ziekte duurt als hoofdregel twee jaar (104 weken); daarna kan een WIA-uitkering volgen."], ["Maximaal 52 weken (één jaar)", "Na 52 weken loopt de loondoorbetaling nog door; in die periode vindt de eerstejaarsevaluatie plaats."], ["Maximaal 26 weken", "Zes maanden is veel te kort; de werkgever draagt het risico twee jaar."], ["Maximaal 156 weken (drie jaar)", "Drie jaar is alleen aan de orde bij een loonsanctie of vrijwillige verlenging, niet als hoofdregel."]], "1b.1"],
["Hoeveel loon moet een werkgever op grond van het Burgerlijk Wetboek minimaal doorbetalen tijdens ziekte?", [["70% van het loon, met in het eerste jaar ten minste het minimumloon", "Dit is de wettelijke ondergrens; de 70% geldt tot een maximum en in het eerste ziektejaar mag de werknemer niet onder het minimumloon uitkomen."], ["100% van het loon gedurende de hele periode van twee jaar", "Volledige doorbetaling komt voor op grond van cao of arbeidsovereenkomst, maar is geen wettelijke verplichting."], ["75% van het loon in de eerste twee maanden en daarna 70%", "Deze opbouw hoort bij de WW en de loongerelateerde WGA-uitkering, niet bij loondoorbetaling bij ziekte."], ["70% van het minimumloon, ongeacht het verdiende loon", "De loondoorbetaling is gekoppeld aan het eigen loon van de werknemer, niet aan een percentage van het minimumloon."]], "1i.8"],
["Binnen welke termijn moet volgens de Wet verbetering poortwachter de probleemanalyse door de bedrijfsarts of arbodienst klaar zijn?", [["Binnen zes weken na de ziekmelding", "De probleemanalyse moet uiterlijk in de zesde ziekteweek worden opgesteld, zodat de re-integratie tijdig kan starten."], ["Binnen twee weken na de ziekmelding", "Zo snel hoeft het niet; de wettelijke termijn voor de probleemanalyse is zes weken."], ["Binnen acht weken na de ziekmelding", "Acht weken is de termijn voor het plan van aanpak, dat op de probleemanalyse volgt."], ["Binnen 42 weken na de ziekmelding", "In week 42 volgt de ziekmelding bij het UWV; de probleemanalyse ligt dan al lang klaar."]], "1i.9"],
["Wat moeten werkgever en werknemer uiterlijk in de achtste ziekteweek samen opstellen?", [["Een plan van aanpak voor de re-integratie", "Op basis van de probleemanalyse leggen werkgever en werknemer in het plan van aanpak vast welke stappen worden gezet om terug te keren naar werk."], ["Een re-integratieverslag voor het UWV", "Het re-integratieverslag hoort bij de WIA-aanvraag aan het einde van de wachttijd, niet bij week acht."], ["Een eerstejaarsevaluatie", "De eerstejaarsevaluatie vindt plaats rond het einde van het eerste ziektejaar."], ["Een vaststellingsovereenkomst", "Een vaststellingsovereenkomst regelt een beëindiging van het dienstverband en is geen re-integratie-instrument."]], "1i.9"],
["Wanneer moet een werkgever een langdurig zieke werknemer uiterlijk ziek melden bij het UWV?", [["In de 42e week van de ziekte", "Een werknemer die nog ziek is, moet uiterlijk in week 42 bij het UWV worden gemeld; dat is de zogenoemde 42e-weekmelding."], ["Op de eerste ziektedag", "Op de eerste ziektedag meldt de werknemer zich ziek bij de werkgever; een melding bij het UWV is dan nog niet nodig."], ["In de zesde week van de ziekte", "In week zes moet de probleemanalyse klaar zijn; de melding bij het UWV volgt later."], ["In de 104e week van de ziekte", "In week 104 eindigt de wachttijd; de WIA moet dan al ruim eerder zijn aangevraagd."]], "1i.9"],
["Sanne (41) is administratief medewerker bij een groothandel en verdient € 3.100 bruto per maand. Zij is getrouwd en heeft twee schoolgaande kinderen. Na een hernia is zij bijna twee jaar ziek en vraagt zij een WIA-uitkering aan. Uit het re-integratieverslag blijkt dat haar werkgever het tweede spoor nooit heeft opgepakt, en het UWV vindt de re-integratie-inspanningen onvoldoende. Wat is het meest waarschijnlijke gevolg?", [["De werkgever moet als loonsanctie maximaal 52 weken langer loon doorbetalen", "Bij onvoldoende re-integratie-inspanningen kan het UWV de loondoorbetalingsplicht met ten hoogste een jaar verlengen."], ["Sanne krijgt geen WIA-uitkering en verliest haar recht op een uitkering definitief", "De sanctie voor tekortschieten van de werkgever treft de werkgever; het recht van Sanne wordt alleen uitgesteld."], ["De werkgever krijgt een boete van de AFM", "De AFM houdt toezicht op de financiële markten en is niet betrokken bij re-integratie."], ["Het UWV neemt de loondoorbetaling direct over en verhaalt die later op de werkgever", "Het UWV neemt de kosten niet over; juist de werkgever moet langer doorbetalen."]], "1k.13"],
["Wat houdt het 'tweede spoor' bij re-integratie in?", [["Re-integratie bij een andere werkgever", "Als terugkeer bij de eigen werkgever niet lukt, moet worden gezocht naar passend werk buiten het bedrijf: het tweede spoor."], ["Re-integratie in het eigen werk of ander werk bij de eigen werkgever", "Dat is het eerste spoor; de eigen werkgever is altijd het eerste uitgangspunt."], ["Een second opinion van een andere bedrijfsarts", "Een second opinion is een recht van de werknemer, maar heet geen tweede spoor."], ["Een aanvraag voor een deskundigenoordeel bij het UWV", "Een deskundigenoordeel kan helpen bij een meningsverschil, maar is geen re-integratiespoor."]], "1i.9"],
["Peter (48) is magazijnmedewerker bij een transportbedrijf en verdient € 2.900 bruto per maand. Hij woont samen en heeft een dochter van twaalf. Na een knieoperatie biedt zijn werkgever hem administratief werk aan, maar Peter vindt dat werk door zijn pijnklachten niet passend. Werkgever en werknemer komen er samen niet uit. Wat kan elk van beiden aanvragen?", [["Een deskundigenoordeel bij het UWV", "Het UWV kan op verzoek een onafhankelijk deskundigenoordeel geven over onder meer passende arbeid en re-integratie-inspanningen."], ["Een uitspraak van het Kifid", "Het Kifid behandelt klachten over financiële dienstverlening, niet over arbeidsrechtelijke re-integratiegeschillen."], ["Een herbeoordeling door de Belastingdienst", "De Belastingdienst heeft geen rol bij de beoordeling van passende arbeid."], ["Een bindend advies van de verzuimverzekeraar", "Een verzuimverzekeraar is partij voor de werkgever en geeft geen onafhankelijk oordeel tussen werkgever en werknemer."]], "1i.9"],
["Mag een werkgever een werknemer ontslaan alleen omdat die langer dan een jaar ziek is?", [["Nee, in de eerste twee ziektejaren geldt een opzegverbod bij ziekte", "Tijdens de eerste twee jaar van ziekte mag de werkgever de arbeidsovereenkomst in beginsel niet wegens ziekte opzeggen."], ["Ja, na 52 weken ziekte vervalt het opzegverbod", "Het opzegverbod is niet beperkt tot het eerste jaar; het geldt in principe twee jaar."], ["Ja, mits de werkgever een verzuimverzekering heeft afgesloten voor het loonrisico", "Een verzuimverzekering dekt het financiële risico van de werkgever en verandert niets aan het ontslagrecht."], ["Nee, een zieke werknemer kan nooit worden ontslagen, ook niet na twee jaar ziekte", "Ook bij ziekte kan ontslag onder voorwaarden mogelijk zijn, bijvoorbeeld na twee jaar of bij een dringende reden."]], "1i.8"],
["Wat kan het gevolg zijn als een zieke werknemer zonder deugdelijke grond weigert passende arbeid te verrichten?", [["De werkgever kan de loondoorbetaling stopzetten", "Een werknemer die zonder goede reden niet meewerkt aan zijn re-integratie, kan zijn recht op loon (tijdelijk) verliezen."], ["De werknemer krijgt direct een WIA-uitkering", "Weigeren mee te werken leidt niet tot een eerdere uitkering, maar juist tot sancties."], ["De werkgever moet het loon verhogen naar 100%", "Er is geen regel die de werkgever verplicht méér te betalen als de werknemer weigert."], ["Het UWV legt de werkgever een loonsanctie op", "Een loonsanctie treft de werkgever die tekortschiet, niet de situatie waarin de werknemer weigert."]], "1k.5"],
["Hoeveel wachtdagen mogen bij ziekte maximaal worden afgesproken, bijvoorbeeld in een cao?", [["Twee wachtdagen", "Wettelijk mogen maximaal twee wachtdagen worden overeengekomen waarover geen loon wordt doorbetaald."], ["Vijf wachtdagen", "Vijf wachtdagen is wettelijk niet toegestaan; het maximum ligt lager."], ["Veertien wachtdagen", "Veertien dagen is een gebruikelijk eigen risico bij verzuimverzekeringen, geen wettelijke wachttijd voor werknemers."], ["Geen enkele, wachtdagen zijn verboden", "Wachtdagen zijn niet verboden; ze mogen worden afgesproken tot het wettelijk maximum."]], "1b.4"],
["Voor wie is de Ziektewet (ZW) in de eerste plaats bedoeld?", [["Zieke werknemers die geen werkgever (meer) hebben die het loon doorbetaalt", "De ZW is een vangnet, bijvoorbeeld voor zieke WW-gerechtigden en flexwerkers van wie het contract tijdens ziekte afloopt."], ["Alle zieke werknemers vanaf de eerste ziektedag", "Werknemers met een werkgever krijgen loon doorbetaald; de ZW is een vangnet voor specifieke groepen."], ["Zelfstandigen zonder arbeidsongeschiktheidsverzekering", "Zelfstandigen vallen niet onder de ZW; zij moeten zich zelf particulier verzekeren."], ["Werknemers die na twee jaar ziekte minder dan 35% arbeidsongeschikt zijn", "Voor deze groep bestaat geen ZW-uitkering; zij hebben geen recht op WIA en worden geacht te werken."]], "1i.2"],
["Kees (29) werkt als monteur bij een installatiebedrijf voor € 2.800 bruto per maand en woont alleen. Hij heeft een tijdelijk contract van een jaar. Drie weken voor het einde van zijn contract breekt hij zijn been bij een sportongeval, waardoor hij nog maanden niet kan werken. Zijn werkgever verlengt het contract niet. Wie zorgt na afloop van het contract voor zijn inkomen bij ziekte?", [["Het UWV via de Ziektewet, tenzij zijn ex-werkgever eigenrisicodrager voor de ZW is", "Na het einde van het dienstverband valt Kees in het vangnet van de ZW; bij eigenrisicodragerschap betaalt de ex-werkgever die uitkering."], ["Zijn ex-werkgever via loondoorbetaling tot het einde van de 104 weken", "Met het einde van het contract eindigt ook de loondoorbetalingsplicht van de werkgever."], ["De gemeente via de Participatiewet", "Bijstand komt pas in beeld als er geen recht is op een werknemersverzekering of ander inkomen."], ["De SVB via de Toeslagenwet", "De Toeslagenwet wordt door het UWV uitgevoerd en vult alleen aan; zij is geen vervanging van de ZW."]], "1b.5"],
["Wat gebeurt er bij de eerstejaars Ziektewet-beoordeling (EZWb) van een vangnetter?", [["Het UWV toetst wat hij nog kan verdienen en of hij daardoor zijn ZW-recht verliest", "Na een jaar ziekte wordt de vangnetter getoetst aan algemeen geaccepteerde arbeid; wie voldoende kan verdienen, verliest de ZW-uitkering."], ["Het UWV beoordeelt of de ex-werkgever een loonsanctie krijgt voor te weinig re-integratie", "Een loonsanctie hoort bij de WIA-aanvraag van een werknemer met werkgever, niet bij de EZWb."], ["Het UWV kent bij een arbeidsongeschiktheid van 80% of meer automatisch een IVA-uitkering toe", "Een IVA-uitkering vraagt een WIA-beoordeling na de wachttijd; de EZWb is daar geen onderdeel van."], ["De bedrijfsarts stelt een plan van aanpak op", "Het plan van aanpak hoort bij het begin van het verzuim, niet bij de beoordeling na een jaar."]], "1i.2"],
["Hoe verhoudt de Ziektewet zich tot de WIA voor een vangnetter die langdurig ziek blijft?", [["De periode van ZW-uitkering telt mee voor de wachttijd van 104 weken voor de WIA", "Ook voor vangnetters geldt een wachttijd van twee jaar; de ZW-periode vult die wachttijd op."], ["De vangnetter moet na de ZW eerst nog twee jaar wachten op de WIA", "De ZW-periode is juist de wachttijd; er komt geen tweede wachttijd achteraan."], ["Een vangnetter heeft nooit recht op een WIA-uitkering", "Vangnetters kunnen na de wachttijd net als andere werknemers een WIA-uitkering krijgen."], ["De ZW loopt altijd door tot de AOW-leeftijd", "De ZW is tijdelijk en duurt maximaal twee jaar; daarna volgt eventueel de WIA."]], "1i.2"],
["Wat is een 'eigenrisicodrager voor de Ziektewet'?", [["Een werkgever die zelf de ZW-uitkeringen en re-integratie van zieke ex-flexwerkers betaalt", "Een ZW-eigenrisicodrager betaalt geen gedifferentieerde ZW-premie aan het UWV, maar draagt zelf het risico voor de vangnetters die van hem afkomstig zijn."], ["Een werknemer die via een eigen verzekering zelf zijn loon in de eerste twee ziektejaren financiert", "Werknemers kunnen geen eigenrisicodrager voor de ZW worden; dat is een keuze van de werkgever."], ["Een zelfstandige die geen AOV heeft gesloten", "Zo'n zelfstandige draagt feitelijk zijn eigen risico, maar heeft niets met de ZW te maken."], ["Een verzekeraar die de ZW-uitkeringen namens het UWV uitvoert voor kleine werkgevers", "Een verzekeraar kan het risico van de werkgever verzekeren, maar de werkgever blijft de eigenrisicodrager."]], "1i.13"],
["Hoe stelt het UWV het arbeidsongeschiktheidspercentage voor de WIA vast?", [["Door het maatmaninkomen te vergelijken met wat hij nog kan verdienen (restverdiencapaciteit)", "Het verlies aan verdiencapaciteit ten opzichte van het maatmaninkomen bepaalt het arbeidsongeschiktheidspercentage."], ["Door het aantal uren dat de werknemer nog werkt te delen door het aantal uren in zijn arbeidsovereenkomst", "De WIA kijkt naar verdiencapaciteit, niet alleen naar het aantal gewerkte uren."], ["Op basis van het oordeel van de behandelend specialist alleen", "De medische beperkingen zijn input; het percentage volgt pas uit de arbeidskundige vergelijking van inkomens."], ["Door de duur van de ziekteperiode in weken om te rekenen naar een percentage van de wachttijd", "Hoe lang iemand ziek is geweest zegt niets over het percentage arbeidsongeschiktheid."]], "1g.14"],
["Wat is het 'maatmaninkomen' in de WIA?", [["Het inkomen dat de werknemer verdiende voordat hij ziek werd", "Het maatmaninkomen is het uitgangspunt waartegen de resterende verdiencapaciteit wordt afgezet."], ["Het inkomen dat een gemiddelde werknemer in Nederland verdient", "Het gaat om het eigen inkomen van de werknemer, niet om een landelijk gemiddelde."], ["Het inkomen dat de werknemer na zijn ziekte nog kan verdienen", "Dat is de resterende verdiencapaciteit, de andere kant van de vergelijking."], ["Het minimumloon dat geldt voor de leeftijd van de werknemer", "Het minimumloon speelt een rol in de WGA-vervolguitkering, maar is niet het maatmaninkomen."]], "1g.14"],
["Ahmed (44) is buschauffeur en verdiende € 3.300 bruto per maand. Hij is getrouwd en heeft drie kinderen. Na een hartinfarct kan hij niet meer als chauffeur werken, maar wel lichter werk doen. Na twee jaar ziekte stelt het UWV vast dat hij 28% arbeidsongeschikt is. Wat betekent dit voor de WIA?", [["Ahmed heeft geen recht op een WIA-uitkering", "Onder de 35% arbeidsongeschiktheid bestaat geen recht op een WIA-uitkering; Ahmed wordt geacht zijn resterende capaciteit te benutten."], ["Ahmed krijgt een WGA-uitkering naar rato van 28%", "De WGA begint pas vanaf 35% arbeidsongeschiktheid."], ["Ahmed krijgt een IVA-uitkering omdat hij langer dan twee jaar ziek is", "De IVA is alleen voor volledig en duurzaam arbeidsongeschikten (80% of meer)."], ["Ahmed krijgt de Ziektewet-uitkering zolang hij niet hersteld is", "De ZW loopt niet door na de WIA-beoordeling bij een werknemer met een werkgever."]], "1d.5"],
["Wie heeft recht op een WGA-uitkering?", [["Wie ten minste 35% arbeidsongeschikt is, maar niet volledig én duurzaam", "De WGA is bedoeld voor gedeeltelijk arbeidsongeschikten en voor volledig arbeidsongeschikten met kans op herstel."], ["Uitsluitend wie volledig en duurzaam arbeidsongeschikt is", "Volledig en duurzaam arbeidsongeschikten vallen onder de IVA."], ["Iedereen die na de wachttijd van 104 weken nog ziek is, ongeacht het percentage", "Er is een ondergrens van 35% arbeidsongeschiktheid."], ["Alleen werknemers die na de wachttijd nog in dienst zijn bij hun eigen werkgever", "Ook wie niet meer in dienst is, kan recht hebben op een WGA-uitkering."]], "1i.12"],
["Lotte (36) is verpleegkundige in een ziekenhuis en verdiende € 3.600 bruto per maand. Zij is alleenstaand en heeft een zoon van acht. Na een zware behandeling voor een ernstige ziekte is zij bij de WIA-beoordeling 85% arbeidsongeschikt. Volgens de verzekeringsarts van het UWV is herstel op termijn goed mogelijk. Welke uitkering krijgt zij?", [["Een WGA-uitkering", "Omdat de arbeidsongeschiktheid niet duurzaam is, valt Lotte ondanks het hoge percentage onder de WGA en niet onder de IVA."], ["Een IVA-uitkering", "De IVA vereist naast 80% of meer arbeidsongeschiktheid ook dat herstel niet of nauwelijks te verwachten is."], ["Geen uitkering, omdat herstel mogelijk is", "Kans op herstel sluit een uitkering niet uit; zij bepaalt alleen welke regeling geldt."], ["Een Wajong-uitkering", "De Wajong is voor mensen die al op jonge leeftijd arbeidsongeschikt zijn; dat speelt bij Lotte niet."]], "1i.11"],
["Hoe hoog is de IVA-uitkering?", [["75% van het (gemaximeerde) dagloon", "De IVA bedraagt 75% van het dagloon, waarbij het dagloon is begrensd tot het maximumdagloon."], ["70% van het minimumloon", "Een percentage van het minimumloon hoort bij de WGA-vervolguitkering, niet bij de IVA."], ["100% van het laatstverdiende loon", "De IVA vult het volledige loon niet aan; bovendien geldt een maximumdagloon."], ["70% van het verschil tussen het dagloon en de restverdiencapaciteit", "Deze berekening lijkt op de loonaanvullingsuitkering in de WGA, niet op de IVA."]], "1i.11"],
["Waarvan hangt de duur van de loongerelateerde WGA-uitkering af?", [["Van het arbeidsverleden, op dezelfde manier als bij de WW", "De loongerelateerde fase duurt net als de WW korter of langer afhankelijk van het arbeidsverleden."], ["Van het arbeidsongeschiktheidspercentage dat het UWV vaststelt", "Het percentage bepaalt of iemand in de WGA valt, maar niet hoe lang de loongerelateerde fase duurt."], ["Van de leeftijd: de uitkering loopt door tot de AOW-leeftijd", "De loongerelateerde fase is juist tijdelijk; daarna volgt de vervolgfase."], ["Van de hoogte van het maatmaninkomen", "Het maatmaninkomen bepaalt het percentage, niet de duur van de loongerelateerde uitkering."]], "1i.12"],
["Casus: Mark krijgt een WGA-uitkering. Zijn loongerelateerde uitkering eindigt. Hij benut minder dan de helft van zijn resterende verdiencapaciteit. Welke uitkering krijgt hij daarna?", [["Een WGA-vervolguitkering, gebaseerd op een percentage van het minimumloon", "Wie zijn restcapaciteit onvoldoende benut, krijgt een vervolguitkering die afhangt van de arbeidsongeschiktheidsklasse en het minimumloon; dat is vaak een forse inkomensdaling."], ["Een loonaanvullingsuitkering van 70% van het verschil tussen maatmaninkomen en restverdiencapaciteit", "De loonaanvullingsuitkering is er alleen voor wie ten minste de helft van zijn restverdiencapaciteit benut."], ["Een IVA-uitkering van 75% van het dagloon", "Het eindigen van de loongerelateerde fase verandert niets aan de vraag of iemand duurzaam volledig arbeidsongeschikt is."], ["Een verlengde loongerelateerde uitkering tot de AOW-leeftijd", "De loongerelateerde fase is in duur begrensd en kan niet worden verlengd tot de AOW-leeftijd."]], "1g.15"],
["Welke voorwaarde geldt voor de WGA-loonaanvullingsuitkering?", [["Hij moet ten minste de helft van zijn resterende verdiencapaciteit benutten", "Wie voldoende werkt, krijgt een aanvulling die is gebaseerd op zijn eigen loon; dit stimuleert werkhervatting."], ["De werknemer moet volledig arbeidsongeschikt zijn", "Een volledig arbeidsongeschikte heeft geen restverdiencapaciteit om te benutten."], ["De werknemer moet jonger zijn dan 50 jaar", "Er geldt geen leeftijdsgrens voor de loonaanvullingsuitkering."], ["De werknemer moet minstens tien jaar bij dezelfde werkgever in dienst zijn geweest", "De duur van het dienstverband bij één werkgever is geen voorwaarde."]], "1g.15"],
["Wat is de belangrijkste reden dat een WGA-gerechtigde na de loongerelateerde fase een groot inkomensverlies kan lijden?", [["De vervolguitkering is bij onvoldoende benutting gebaseerd op het minimumloon, niet op het eigen loon", "Dit inkomensgat heet het WGA-hiaat en is de reden voor het bestaan van de WGA-hiaatverzekering."], ["De WGA-uitkering wordt na de loongerelateerde fase altijd stopgezet, ongeacht hoeveel iemand nog werkt", "De uitkering stopt niet, maar wordt in de vervolgfase anders berekend."], ["De werkgever moet vanaf dat moment het eerder doorbetaalde loon terugvorderen", "Een werkgever heeft geen terugvorderingsrecht op eerder betaald loon."], ["Het UWV verrekent vanaf de vervolgfase het eigen vermogen en spaargeld van de werknemer met de uitkering", "Er is geen vermogenstoets in de WGA; die geldt wel in de bijstand."]], "1i.12"],
["Welke drempel wordt in de WIA gehanteerd om 'volledig' arbeidsongeschikt te zijn?", [["80% of meer", "Vanaf 80% arbeidsongeschiktheid is iemand volledig arbeidsongeschikt; bij duurzaamheid volgt de IVA, anders de WGA 80-100."], ["Precies 100%", "Ook wie niet volledig 100% verdiencapaciteit verliest, kan als volledig arbeidsongeschikt gelden."], ["65% of meer", "65% is geen drempel in de WIA."], ["35% of meer", "35% is de ondergrens voor een WIA-uitkering, niet de grens voor volledige arbeidsongeschiktheid."]], "1i.11"],
["Ilse (24) was na haar studie pas vijf maanden in dienst als verkoopmedewerker bij een modezaak toen zij ziek werd. Zij verdiende € 2.300 bruto per maand en woont samen met haar vriend. Daarvoor had zij nooit in loondienst gewerkt. Na twee jaar ziekte wordt zij 40% arbeidsongeschikt verklaard en blijkt dat zij niet aan de referte-eis voldoet. Wat betekent dit voor haar WGA-uitkering?", [["Zij slaat de loongerelateerde fase over en gaat direct naar de vervolgfase", "Wie niet aan de referte-eis voldoet, heeft geen recht op de loongerelateerde uitkering en gaat direct naar de vervolgfase."], ["Zij krijgt geen enkele WIA-uitkering", "Het niet halen van de referte-eis sluit alleen de loongerelateerde fase uit, niet de hele WGA."], ["Zij krijgt als compensatie een IVA-uitkering van 75% van het dagloon", "De IVA hangt af van volledige en duurzame arbeidsongeschiktheid, niet van de referte-eis."], ["Zij moet eerst nog een jaar Ziektewet-uitkering ontvangen voordat de WGA ingaat", "De referte-eis zegt niets over een extra periode in de Ziektewet."]], "1i.12"],
["Wie is in de WIA een '35-minner'?", [["Een werknemer die na de wachttijd minder dan 35% arbeidsongeschikt is", "Deze werknemer krijgt geen WIA-uitkering; de werkgever wordt geacht passend werk te bieden of de werknemer kan elders werk zoeken."], ["Een werknemer die jonger is dan 35 jaar en al een WIA-uitkering ontvangt", "De term verwijst naar het arbeidsongeschiktheidspercentage, niet naar de leeftijd."], ["Een werknemer die minder dan 35 uur per week werkt", "Het aantal contracturen staat los van deze term."], ["Een werknemer die korter dan 35 weken ziek is geweest vóór de WIA-aanvraag", "De term heeft niets met de ziekteduur te maken."]], "1d.5"],
["Wat geldt voor de verdiencapaciteit die het UWV vaststelt voor de WIA?", [["Het UWV gaat uit van geduide functies die hij nog kan vervullen, ook zonder baan", "De beoordeling is gebaseerd op geduide functies op de arbeidsmarkt, los van de vraag of de werknemer een baan vindt."], ["Het UWV kijkt alleen naar passende functies die bij de eigen werkgever beschikbaar zijn", "Bij de WIA-beoordeling wordt de hele arbeidsmarkt betrokken, niet alleen de eigen werkgever."], ["Het UWV gaat uit van het werk dat de werknemer zelf het liefst wil doen na zijn herstel", "Persoonlijke voorkeur speelt geen rol; het gaat om wat hij nog kan."], ["Het UWV kijkt alleen naar het eigen beroep dat de werknemer vóór zijn ziekte uitoefende", "Een beroepsarbeidsongeschiktheidscriterium hoort bij sommige particuliere AOV's, niet bij de WIA."]], "1g.16"],
["Voor wie is de Wajong bedoeld?", [["Wie vóór zijn 18e of tijdens een studie arbeidsongeschikt is geworden", "De Wajong is voor jonggehandicapten: wie vóór zijn 18e, of tijdens een studie vóór zijn 30e, langdurig ziek of gehandicapt raakt."], ["Werknemers die na twee jaar ziekte niet volledig herstellen van hun aandoening", "Zij vallen onder de WIA, niet onder de Wajong."], ["Zelfstandigen jonger dan 30 jaar zonder AOV", "Zelfstandig ondernemerschap geeft geen recht op de Wajong."], ["Jongeren die na het afronden van hun opleiding geen baan kunnen vinden", "Werkloosheid zonder arbeidsongeschiktheid geeft geen recht op de Wajong."]], "1i.2"],
["Wat geldt sinds 2015 voor nieuwe instroom in de Wajong?", [["Alleen wie duurzaam geen arbeidsvermogen heeft, kan nog Wajong krijgen", "Sinds de invoering van de Participatiewet is de Wajong beperkt tot jonggehandicapten zonder arbeidsvermogen; anderen vallen onder de gemeente."], ["Iedere jonggehandicapte krijgt een Wajong-uitkering tot de leeftijd van 27 jaar", "Er bestaat geen algemene Wajong-uitkering meer voor iedere jonggehandicapte."], ["De Wajong is in 2015 volledig afgeschaft", "De Wajong bestaat nog, maar alleen voor een beperkte groep."], ["De Wajong wordt sinds 2015 door de SVB uitgevoerd", "De Wajong wordt uitgevoerd door het UWV."]], "1i.2"],
["Een werkgever sluit een nieuwe verzuimverzekering af. Eén werknemer is op de ingangsdatum al ziek. Hoe gaat een verzekeraar in de regel met dit inlooprisico om?", [["Lopend verzuim is uitgesloten, tenzij inloop uitdrukkelijk is meeverzekerd", "Een verzekeraar dekt liever geen risico dat zich al heeft voorgedaan. Lopende ziektegevallen vallen daarom meestal buiten de dekking of alleen onder aparte voorwaarden."], ["Het lopende verzuim is altijd vanaf de eerste ziektedag gedekt", "Dan zou een werkgever pas verzekeren als er al iemand ziek is; daarom sluiten verzekeraars lopend verzuim meestal uit."], ["De werkgever mag die werknemer pas verzekeren als hij in de WIA zit", "De WIA volgt na twee jaar; een verzuimverzekering dekt juist de periode daarvoor."], ["De verzekeraar weigert de hele werkgever als verzekeringnemer", "Een lopend ziektegeval leidt meestal tot uitsluiting van dat geval, niet tot weigering van de hele polis."]], "1g.12"],
["Wat is de referte-eis in de WW?", [["In de 36 weken vóór werkloosheid ten minste 26 weken hebben gewerkt", "Wie aan de referte-eis voldoet, heeft recht op een basis-WW-uitkering."], ["In de vijf jaar vóór werkloosheid ten minste vier jaar hebben gewerkt", "Dat lijkt op de jareneis, die bepaalt of iemand recht heeft op een langere WW."], ["Ten minste één jaar bij de laatste werkgever in dienst zijn geweest", "De referte-eis kijkt naar gewerkte weken, ongeacht bij welke werkgever."], ["Ten minste 26 weken WW-premie zelf hebben betaald", "De WW-premie wordt door de werkgever afgedragen; de referte-eis gaat over gewerkte weken."]], "1i.2"],
["Jeroen (31) is ICT-consultant in loondienst en verdient € 4.200 bruto per maand. Hij is vrijgezel en heeft geen kinderen. Zonder dringende reden zegt hij zelf zijn vaste baan op om twee maanden te gaan reizen. Na terugkomst vindt hij niet direct ander werk en vraagt hij WW aan. Wat is het uitgangspunt?", [["Hij heeft geen recht op WW, want hij is verwijtbaar werkloos", "Wie zonder goede reden zelf ontslag neemt, is verwijtbaar werkloos en krijgt geen WW."], ["Hij heeft recht op WW, maar pas na een wachttijd van drie maanden", "Een wachttijd vervangt het verval van het recht niet; bij verwijtbare werkloosheid is er geen uitkering."], ["Hij heeft recht op WW, omdat hij aan de referte-eis voldoet", "Voldoen aan de referte-eis is niet voldoende als de werkloosheid verwijtbaar is."], ["Hij heeft recht op een halve WW-uitkering", "Een gedeeltelijke uitkering is niet de sanctie bij verwijtbare werkloosheid."]], "1i.2"],
["Hoe wordt inkomen uit werk tijdens een WW-uitkering verrekend?", [["70% van het inkomen wordt verrekend met de WW-uitkering", "Door slechts 70% te verrekenen loont het om tijdens de WW (gedeeltelijk) te werken."], ["Het verdiende inkomen wordt volledig in mindering gebracht", "Volledige verrekening zou werken ontmoedigen; de WW verrekent 70%."], ["Inkomen uit werk wordt niet verrekend", "Inkomen uit werk tijdens de WW wordt wel degelijk verrekend."], ["De WW stopt zodra er enig inkomen wordt verdiend", "De WW stopt niet direct; er wordt verrekend en pas bij voldoende inkomen eindigt de uitkering."]], "1i.2"],
["Een zelfstandige heeft bij twee verzekeraars een inkomensverzekering met schadedekking, die allebei hetzelfde inkomensverlies dekken. Wat betekent deze samenloop voor de schadeafwikkeling?", [["Hij krijgt in totaal niet meer dan zijn werkelijke schade; de verzekeraars verdelen die onderling", "Bij samenloop van schadeverzekeringen mag de verzekerde niet aan de schade verdienen (indemniteitsbeginsel). De verzekeraars dragen de schade naar verhouding."], ["Beide verzekeraars keren het volledige bedrag uit, zodat hij dubbel ontvangt", "Dat kan bij sommenverzekeringen, maar niet bij schadeverzekeringen."], ["Alleen de verzekering die het laatst is afgesloten keert uit", "Er is geen regel dat de jongste polis voorgaat; de wet en de samenloopbepalingen regelen de verdeling."], ["Geen van beide keert uit, omdat dubbele verzekering verboden is", "Dubbel verzekeren is niet verboden; het leidt alleen niet tot een hogere vergoeding dan de schade."]], "1k.4"],
["Fatima (39) is doktersassistente bij een gezondheidscentrum en verdient € 2.600 bruto per maand voor 32 uur per week. Zij is getrouwd en heeft twee kinderen op de basisschool. Zij werkt al jaren onafgebroken bij dezelfde werkgever. Door een reorganisatie vervallen 12 van haar 32 contracturen per week, met behoud van de rest van haar baan. Kan zij in beginsel WW krijgen?", [["Ja, zij verliest ten minste vijf uur per week en kan voor die uren WW krijgen", "Ook gedeeltelijke werkloosheid kan recht geven op WW als het urenverlies groot genoeg is en aan de overige voorwaarden is voldaan."], ["Nee, WW is alleen mogelijk als alle contracturen tegelijk vervallen", "De WW kent ook gedeeltelijke werkloosheid."], ["Nee, zij moet eerst minstens de helft van haar contracturen per week verliezen", "Die halveringsregel geldt alleen voor werknemers die minder dan tien uur per week werkten."], ["Ja, maar alleen als zij ouder is dan 50 jaar", "Leeftijd is geen voorwaarde voor recht op WW."]], "1i.2"],
["Peter (45) was vrachtwagenchauffeur en is getrouwd met Marieke (43). Marieke werkt fulltime als docent en verdient € 4.000 bruto per maand. Hun kinderen zijn 19 en 21 jaar. Peter overlijdt plotseling aan een hartstilstand; Marieke is niet arbeidsongeschikt. Heeft Marieke recht op een Anw-uitkering?", [["Nee, er is geen kind onder de 18 en zij is niet arbeidsongeschikt", "Zonder kind onder de 18, zonder 45% arbeidsongeschiktheid en geboren na 1950 heeft Marieke geen recht op een Anw-nabestaandenuitkering."], ["Ja, iedere nabestaande partner krijgt een Anw-uitkering tot de AOW-leeftijd", "De Anw kent strikte toegangsvoorwaarden; niet iedere partner heeft recht."], ["Ja, maar alleen tot het jongste kind de leeftijd van 21 jaar bereikt", "De leeftijdsgrens voor kinderen in de Anw ligt bij 18 jaar, en die is hier al gepasseerd."], ["Ja, omdat zij minder verdient dan Peter", "Een inkomensverschil tussen partners geeft geen recht op Anw."]], "1i.2"],
["Welk inkomen wordt NIET verrekend met een Anw-nabestaandenuitkering?", [["Een uitkering uit een particuliere ORV", "Uitkeringen uit een particuliere ORV worden niet gekort op de Anw; daardoor is een ORV goed te combineren met een Anw-recht."], ["Inkomen uit arbeid in loondienst of als zelfstandige", "Inkomen uit arbeid wordt (deels) verrekend met de Anw-uitkering."], ["Een WIA-uitkering na langdurige arbeidsongeschiktheid", "Uitkeringen die het inkomen uit arbeid vervangen, worden in de Anw wel verrekend."], ["Een ZW-uitkering bij ziekte als vangnetter", "Ook een ZW-uitkering vervangt loon en wordt verrekend met de Anw."]], "1i.2"],
["Wat regelt een spijtoptantenregeling bij een collectieve werknemersverzekering, zoals een WGA-hiaatverzekering met werknemersbijdrage?", [["Werknemers die eerder afzagen van deelname, kunnen later onder voorwaarden alsnog instappen", "Zo'n regeling geeft een tweede kans om aan te sluiten. De verzekeraar stelt daarbij meestal voorwaarden, zoals een gezondheidsverklaring of een termijn, om antiselectie te voorkomen."], ["Werknemers kunnen na het ontstaan van arbeidsongeschiktheid met terugwerkende kracht deelnemen", "Instappen nadat het risico zich heeft voorgedaan, zou het verzekeringsprincipe ondermijnen."], ["Werkgevers kunnen de collectieve polis zonder opzegtermijn beëindigen", "Een spijtoptantenregeling gaat over werknemers die later willen deelnemen, niet over opzegging door de werkgever."], ["Werknemers krijgen hun betaalde premie terug als zij nooit arbeidsongeschikt worden", "Een risicoverzekering kent geen premierestitutie als er geen schade is."]], "1h.10"],
["Wat gebeurt er met een Anw-nabestaandenuitkering als de nabestaande gaat samenwonen of hertrouwt?", [["De uitkering stopt", "Bij een nieuw huwelijk of samenwonen met een nieuwe partner eindigt het recht op Anw."], ["De uitkering loopt ongewijzigd door", "Een nieuwe relatie met gezamenlijke huishouding beëindigt juist het recht."], ["De uitkering wordt gehalveerd", "Er is geen halvering; het recht eindigt."], ["De uitkering gaat over op de nieuwe partner", "Een Anw-uitkering is persoonlijk en gaat nooit over op een nieuwe partner."]], "1i.2"],
["Tot welke leeftijd heeft een wees in beginsel recht op een Anw-wezenuitkering?", [["Tot 16 jaar; bij studie of arbeidsongeschiktheid tot 21 jaar", "Na 16 jaar loopt de wezenuitkering alleen door bij bijvoorbeeld een opleiding of arbeidsongeschiktheid, tot uiterlijk 21 jaar."], ["Tot 18 jaar, ongeacht of de wees nog studeert, werkt of arbeidsongeschikt is", "18 jaar is de leeftijdsgrens voor het kind bij de nabestaandenuitkering van de partner, niet bij de wezenuitkering."], ["Tot 27 jaar als de wees een voltijdopleiding volgt", "27 jaar is geen grens in de Anw."], ["Levenslang als beide ouders zijn overleden (volle wees)", "De wezenuitkering is altijd tijdelijk."]], "1i.2"],
["Waarvoor dient een Anw-hiaatverzekering?", [["Het gat dekken als er geen of maar een beperkt recht op Anw is", "Een Anw-hiaatverzekering keert uit bij overlijden en vult het ontbrekende Anw-recht aan, vaak aangeboden via de pensioenregeling."], ["Om het verschil tussen WW en het laatstverdiende loon te dekken", "Dat gat heeft niets met overlijden te maken en wordt niet door een Anw-hiaatverzekering gedekt."], ["Om de AOW van de langstlevende te verhogen", "De Anw-hiaatverzekering stopt in de regel bij de AOW-leeftijd en verhoogt de AOW niet."], ["Om uitvaartkosten te betalen", "Uitvaartkosten worden gedekt door een uitvaartverzekering."]], "1g.22"],
["Na beoordeling van de gezondheidsverklaring kan een verzekeraar een AOV-aanvraag op verschillende manieren accepteren. Welke beslissing is GEEN gebruikelijke acceptatiebeslissing?", [["Acceptatie onder voorwaarde dat de klant geen andere verzekeringen meer sluit", "Zo'n voorwaarde hoort niet bij medische acceptatie. Gebruikelijk zijn standaardacceptatie, een premietoeslag, een uitsluiting, een aangepaste wachttijd of afwijzing."], ["Acceptatie met een uitsluitingsclausule voor een bestaande aandoening", "Een uitsluiting is een veelvoorkomende acceptatiebeslissing bij een bekende aandoening."], ["Acceptatie tegen een premietoeslag", "Een premietoeslag is een gebruikelijke manier om een verhoogd risico toch te accepteren."], ["Acceptatie met een langere wachttijd of een beperkte uitkeringsduur", "Ook een aangepaste wachttijd of uitkeringsduur komt voor als beperkende voorwaarde."]], "1h.1"],
["Hoeveel AOW-opbouw mist iemand per jaar dat hij in de 50 jaar vóór zijn AOW-leeftijd niet in Nederland woonde of werkte?", [["2% per jaar", "De AOW wordt opgebouwd over 50 jaar, met 2% per verzekerd jaar; elk niet-verzekerd jaar kost 2% van de volledige AOW."], ["1% per jaar", "Bij 1% zou de opbouw 100 jaar duren; de AOW-periode is 50 jaar."], ["5% per jaar", "5% per jaar past niet bij een opbouwperiode van 50 jaar."], ["Niets, de AOW wordt altijd volledig uitgekeerd", "Wie niet verzekerd was, krijgt een gekorte AOW."]], "1i.2"],
["Mag een werkgever de premie voor de WGA die hij als onderdeel van de premie Werkhervattingskas betaalt, verhalen op zijn werknemers?", [["Ja, hij mag maximaal de helft van de WGA-premie op het nettoloon van de werknemer verhalen", "De wet staat verhaal toe van ten hoogste de helft van de WGA-premie; voor het overige deel van de premie Werkhervattingskas geldt dat niet."], ["Ja, de volledige premie mag op het brutoloon worden ingehouden", "Verhaal is begrensd tot maximaal de helft van de WGA-premie."], ["Nee, alle premies voor werknemersverzekeringen komen altijd volledig voor rekening van de werkgever", "Voor de WGA-premie geldt juist een uitzondering die gedeeltelijk verhaal toestaat."], ["Alleen als de werknemer meer verdient dan het maximumdagloon", "De hoogte van het loon bepaalt niet of verhaal is toegestaan."]], "1i.3"],
["Hans is technisch tekenaar en bereikt dit jaar de AOW-leeftijd. Hij verdiende € 3.800 bruto per maand en krijgt straks daarnaast een bescheiden pensioen. Zijn vrouw Ellen is acht jaar jonger en heeft geen eigen inkomen. Hun kinderen wonen al op zichzelf. Wat is het uitgangspunt voor hun AOW?", [["Hans krijgt een AOW voor gehuwden; voor Ellen is er geen partnertoeslag meer", "De AOW-partnertoeslag is per 2015 afgeschaft; het huishouden kan dus een inkomensgat hebben tot Ellen zelf AOW krijgt."], ["Hans krijgt een AOW voor alleenstaanden tot Ellen de AOW-leeftijd bereikt", "Gehuwden krijgen de AOW voor gehuwden, ook als de partner nog geen AOW ontvangt."], ["Ellen krijgt direct ook AOW omdat haar man AOW krijgt", "AOW is een persoonlijk recht dat ingaat op de eigen AOW-leeftijd."], ["Hans krijgt een partnertoeslag van de SVB tot Ellen AOW krijgt", "De partnertoeslag bestaat niet meer voor wie na 2014 AOW-gerechtigd werd."]], "1i.2"],
["Waarop is de stijging van de AOW-leeftijd gebaseerd?", [["Op de ontwikkeling van de levensverwachting", "De AOW-leeftijd is wettelijk gekoppeld aan de gemiddelde resterende levensverwachting en wordt enkele jaren vooruit vastgesteld."], ["Op de hoogte van de inflatie", "Inflatie beïnvloedt de hoogte van de AOW-bedragen, niet de AOW-leeftijd."], ["Op de dekkingsgraad van pensioenfondsen", "De dekkingsgraad gaat over pensioenfondsen, niet over de AOW."], ["Op het aantal gewerkte jaren van de persoon zelf", "De AOW-leeftijd is voor iedereen van dezelfde geboortedatum gelijk."]], "1i.2"],
["Welk arbeidsongeschiktheidscriterium in een AOV biedt de zelfstandige de ruimste dekking?", [["Beroepsarbeidsongeschiktheid", "Bij dit criterium is de verzekerde al arbeidsongeschikt als hij zijn eigen beroep niet meer kan uitoefenen, ook als hij ander werk nog wel kan doen."], ["Passende arbeidsongeschiktheid", "Bij passende arbeid wordt ook gekeken naar ander werk dat past bij opleiding en ervaring; dat is beperkter dan het eigen beroep."], ["Gangbare arbeidsongeschiktheid", "Bij gangbare arbeid wordt getoetst aan vrijwel alle algemeen geaccepteerde arbeid; dat is het smalste criterium."], ["Arbeidsongeschiktheid volgens de WIA-maatstaf", "De WIA-maatstaf kijkt naar de hele arbeidsmarkt en is daardoor juist beperkt voor de verzekerde."]], "1g.8"],
["Floor (42) is zelfstandig tandarts met een eigen praktijk en maakt € 110.000 winst per jaar. Zij is getrouwd en heeft twee kinderen. Door een complexe handblessure kan zij geen behandelingen meer uitvoeren. Zij zou wel als docent tandheelkunde aan een opleiding kunnen werken. Bij welke AOV-dekking krijgt zij het meest waarschijnlijk een uitkering?", [["Bij een dekking op basis van beroepsarbeidsongeschiktheid", "Floor kan haar eigen beroep niet meer uitoefenen; bij een beroepsdekking is dat voldoende voor een uitkering."], ["Bij een dekking op basis van passende arbeid", "Werk als docent tandheelkunde past bij haar opleiding en ervaring, waardoor een passende-arbeiddekking mogelijk niet of minder uitkeert."], ["Bij een dekking op basis van gangbare arbeid", "Bij gangbare arbeid wordt ook naar ander algemeen werk gekeken; dat dekt haar situatie het minst."], ["Bij elke dekking in gelijke mate, omdat het criterium niet uitmaakt", "Het arbeidsongeschiktheidscriterium bepaalt juist aan welk werk Floor wordt getoetst en dus of en hoeveel er wordt uitgekeerd."]], "1g.16"],
["Wat is het effect van een langere wachttijd (eigenrisicoperiode) in een AOV?", [["Lagere premie, maar de verzekerde moet de eerste periode zelf overbruggen", "Een langere wachttijd verkleint het risico voor de verzekeraar; de zelfstandige moet wel voldoende buffer hebben."], ["De premie wordt hoger, omdat de verzekeraar over een langere periode moet uitkeren", "Bij een langere wachttijd begint de uitkering later; de premie daalt juist."], ["De uitkering wordt hoger als compensatie voor het wachten", "De hoogte van de uitkering hangt af van het verzekerde bedrag, niet van de wachttijd."], ["Er verandert niets aan premie of dekking", "De wachttijd is een belangrijke premiebepalende factor."]], "1g.8"],
["Dirk (38) is zelfstandig loodgieter en maakt € 52.000 winst per jaar. Hij woont samen en hun dochter is drie. Hij heeft een spaarbuffer opgebouwd waarmee hij zes maanden vaste lasten kan betalen. Bij het afsluiten van zijn AOV wil hij zo min mogelijk premie betalen. Welke keuze ligt het meest voor de hand?", [["Een langere wachttijd kiezen die past bij zijn buffer", "Met zijn buffer kan Dirk de eerste maanden zelf overbruggen; een langere wachttijd verlaagt de premie aanzienlijk."], ["Een zo kort mogelijke wachttijd kiezen", "Een korte wachttijd geeft de hoogste premie, terwijl Dirk zijn buffer dan niet benut."], ["Het verzekerd bedrag hoger zetten dan zijn inkomen", "Oververzekeren verhoogt de premie en wordt door verzekeraars beperkt."], ["De eindleeftijd van de AOV zo hoog mogelijk kiezen", "Een hogere eindleeftijd verlengt de dekking, maar verhoogt juist de premie."]], "1g.8"],
["Waarom accepteren verzekeraars bij een AOV doorgaans geen verzekerd bedrag dat gelijk is aan of hoger is dan het volledige inkomen?", [["Om oververzekering te voorkomen en de prikkel tot werkhervatting te behouden", "Als een uitkering even hoog of hoger is dan het inkomen, verdwijnt de financiële prikkel om weer aan het werk te gaan."], ["Omdat de Wft een maximum van 50% van het inkomen voorschrijft", "De Wft schrijft geen maximumpercentage voor het verzekerd bedrag voor."], ["Omdat de Belastingdienst een hogere uitkering niet toestaat", "Fiscaal is er geen verbod; het maximum is een acceptatiebeleid van verzekeraars."], ["Omdat de premie anders niet aftrekbaar is", "De aftrekbaarheid van de premie hangt niet af van de verhouding tussen verzekerd bedrag en inkomen."]], "1g.6"],
["Wat is het verschil tussen een AOV als sommenverzekering en als schadeverzekering?", [["Sommen: een vooraf afgesproken bedrag; schade: vergoeding van het werkelijke inkomensverlies", "Bij een schadeverzekering moet de verzekerde het inkomensverlies aantonen; bij een sommenverzekering hangt de uitkering af van het verzekerde bedrag en het AO-percentage."], ["Een sommenverzekering keert alleen uit bij overlijden", "Uitkeren bij overlijden is kenmerkend voor een ORV, niet voor het verschil tussen sommen- en schadeverzekeringen."], ["Bij een schadeverzekering is de premie altijd fiscaal aftrekbaar en bij een sommenverzekering nooit", "De fiscale behandeling hangt niet af van dit onderscheid."], ["Een schadeverzekering heeft nooit een wachttijd", "Ook een AOV op schadebasis kent een wachttijd."]], "1f.2"],
["Wat houdt een gezondheidsclausule (uitsluiting) in een AOV in?", [["Arbeidsongeschiktheid door een vooraf bekende aandoening is niet gedekt", "Bij een bestaand gezondheidsrisico kan de verzekeraar de dekking accepteren onder uitsluiting van die aandoening."], ["De verzekerde moet jaarlijks een medische keuring bij de verzekeraar ondergaan", "Een jaarlijkse keuring is geen standaardonderdeel van een AOV of uitsluiting."], ["De verzekeraar mag de polis op elk moment opzeggen", "Een uitsluiting gaat over de dekking, niet over een opzeggingsrecht."], ["De premie wordt altijd verdubbeld", "Een premieopslag is een ander instrument dan een uitsluiting en is niet vast verdubbeld."]], "1h.1"],
["Jan (50) is zelfstandig schilder en maakt € 45.000 winst per jaar. Hij is getrouwd en zijn kinderen wonen niet meer thuis. Zijn AOV keert pas uit vanaf 25% arbeidsongeschiktheid. Na een schouderblessure stelt de verzekeraar vast dat hij 20% arbeidsongeschikt is. Wat is het gevolg?", [["Jan krijgt geen uitkering, want hij blijft onder de polisdrempel", "De uitkering begint pas als het in de polis afgesproken minimum-AO-percentage wordt gehaald."], ["Jan krijgt 20% van het verzekerd bedrag, naar rato van zijn arbeidsongeschiktheid", "Onder de polisdrempel wordt niet uitgekeerd, ook niet naar rato."], ["Jan krijgt 25% van het verzekerd bedrag, het minimum volgens de polis", "Een uitkering naar de drempel zelf bestaat niet; hij is minder arbeidsongeschikt dan de drempel."], ["Jan krijgt een uitkering uit de WIA", "Als zelfstandige is Jan in de regel niet verzekerd voor de WIA."]], "1g.3"],
["Wat is een broodfonds?", [["Een groep zelfstandigen die elkaar bij ziekte tijdelijk steunt met schenkingen", "Een broodfonds is geen verzekering; deelnemers storten maandelijks en schenken een zieke deelnemer een tijdelijk inkomen."], ["Een verplichte publieke AOV voor zelfstandigen, uitgevoerd door het UWV", "Een broodfonds is vrijwillig en wordt door de deelnemers zelf georganiseerd."], ["Een AOV van een verzekeraar met een korte uitkeringsduur van maximaal twee jaar", "Een broodfonds is geen verzekeringsproduct van een verzekeraar."], ["Een spaarrekening bij de bank voor ondernemers", "Een broodfonds werkt als collectief van schenkingen, niet als individuele spaarrekening."]], "1d.6"],
["Ruud (47) is directeur-grootaandeelhouder (dga) van zijn eigen adviesbureau en keert zichzelf via de bv € 85.000 per jaar aan salaris uit. Hij is getrouwd en heeft twee tieners. Omdat hij de zeggenschap in de bv heeft, is hij niet verzekerd voor de werknemersverzekeringen. Hij vraagt wat er gebeurt als hij langdurig ziek wordt. Wat volgt hieruit voor zijn inkomensadvies?", [["Hij valt buiten ZW en WIA en moet zijn arbeidsongeschiktheidsrisico zelf regelen", "Een dga die niet verzekerd is voor de werknemersverzekeringen, valt buiten ZW, WIA en WW; een AOV ligt dan voor de hand."], ["De bv betaalt hem verplicht twee jaar loon door en daarna volgt een WIA-uitkering van het UWV", "Zonder werknemersverzekeringen is er geen WIA na twee jaar."], ["Hij krijgt bij arbeidsongeschiktheid een Wajong-uitkering", "De Wajong is voor jonggehandicapten en niet bedoeld voor dga's."], ["Hij is automatisch verzekerd via de AOW", "De AOW is een ouderdomsvoorziening en dekt geen arbeidsongeschiktheid."]], "1a.8"],
["Wat is op hoofdlijnen de bedoeling van de voorgenomen basisverzekering arbeidsongeschiktheid voor zelfstandigen?", [["Een verplichte publieke basisdekking rond minimumloonniveau, met ruimte om particulier aan te vullen", "Het kabinet werkt aan een verplichte basisdekking voor zelfstandigen; voor een inkomen boven dat niveau of een kortere wachttijd blijft een particuliere AOV nodig. Controleer de actuele stand van het wetsvoorstel."], ["Een verplichte particuliere AOV op beroepsbasis voor alle zelfstandigen, uit te voeren door verzekeraars", "De basisverzekering is een publieke regeling en geen verplichte particuliere beroepsdekking."], ["Een vrijwillige spaarregeling via de Belastingdienst", "Het gaat om een verzekering tegen langdurige arbeidsongeschiktheid, niet om een spaarregeling."], ["Een uitbreiding van de Wajong naar alle zelfstandigen zonder eigen AOV", "De Wajong blijft voor jonggehandicapten; de basisverzekering is een aparte regeling."]], "1i.7"],
["Noor (33) is zelfstandig fotograaf en maakt € 40.000 winst per jaar. Zij woont samen en verwacht haar eerste kind. Zij heeft een AOV, maar leest dat er een verplichte basisverzekering arbeidsongeschiktheid voor zelfstandigen komt. Om premie te besparen vraagt zij of zij haar AOV nu al kan opzeggen. Wat is een zorgvuldig advies?", [["Niet opzeggen: de regeling is er nog niet en biedt straks alleen een basisniveau na lange wachttijd", "Zolang de regeling niet in werking is, is Noor niet verzekerd; ook daarna is aanvulling vaak nodig voor inkomen boven het basisniveau en de eerste periode."], ["Opzeggen, omdat de basisverzekering met terugwerkende kracht dekking geeft vanaf de aankondiging", "Er is geen aanwijzing dat de regeling met terugwerkende kracht dekking biedt."], ["Opzeggen, omdat de basisverzekering het volledige inkomen vervangt", "De voorgenomen uitkering is juist een basisniveau en vervangt een hoger inkomen niet volledig."], ["Opzeggen en het geld sparen, omdat deelname aan een broodfonds wettelijk verplicht wordt voor zzp'ers", "Een broodfonds wordt niet wettelijk verplicht."]], "1i.7"],
["Wat dekt een WIA-excedentverzekering?", [["Het inkomensverlies over het deel van het loon boven het maximumdagloon", "De WIA verzekert alleen loon tot het maximumdagloon; de excedentverzekering vult het verlies over het meerdere aan."], ["Het inkomensverlies tijdens de eerste twee ziektejaren", "In de eerste twee jaar betaalt de werkgever loon door; dat gat dekt de excedentverzekering niet."], ["Het inkomensverlies bij werkloosheid boven de WW", "Werkloosheid valt buiten de WIA-excedentverzekering."], ["De uitvaartkosten bij overlijden na arbeidsongeschiktheid", "Uitvaartkosten worden gedekt door een uitvaartverzekering."]], "1g.13"],
["Marloes (45) is financieel manager bij een bouwbedrijf en verdient € 9.000 bruto per maand, ruim boven het maximumdagloon. Zij is gescheiden en zorgt voor twee kinderen. Haar werkgever biedt een collectieve WGA-hiaatverzekering, maar geen WIA-excedentverzekering. Zij vraagt wat er gebeurt als zij langdurig arbeidsongeschikt wordt. Welk risico blijft voor haar bestaan?", [["Haar loon boven het maximumdagloon is bij arbeidsongeschiktheid onverzekerd", "De WGA-hiaatverzekering vult het gat tot het niveau van het (gemaximeerde) WIA-loon aan; voor het loon daarboven is een excedentdekking nodig."], ["Zij is niet verzekerd tijdens de eerste twee ziektejaren", "In de eerste twee jaar geldt de loondoorbetaling door de werkgever."], ["Zij krijgt geen WGA-uitkering, omdat haar loon boven het maximumdagloon ligt", "Een hoog inkomen sluit de WGA niet uit; alleen het dagloon is gemaximeerd."], ["Haar WGA-hiaatverzekering vervalt bij een hoog inkomen", "Een hoog inkomen is geen vervalgrond van de WGA-hiaatverzekering."]], "1g.13"],
["Wanneer komt een WGA-hiaatverzekering in de regel tot uitkering?", [["Als de werknemer in de WGA-vervolgfase een uitkering op minimumloonniveau krijgt", "De WGA-hiaatverzekering vult de vaak lage vervolguitkering aan; dat is het WGA-hiaat."], ["Vanaf de eerste ziektedag", "In de eerste twee jaar is er loondoorbetaling en is er nog geen WGA."], ["Alleen bij een IVA-uitkering", "Bij de IVA is er geen WGA-vervolgfase, en dus geen WGA-hiaat."], ["Alleen als de werknemer na de wachttijd minder dan 35% arbeidsongeschikt is verklaard", "Onder de 35% is er geen WGA-uitkering; daarvoor bestaan aparte 'WIA 35-min'-dekkingen."]], "1g.13"],
["Hoe wordt een uitkering uit een collectieve WIA-excedentverzekering die via de werkgever loopt fiscaal in de regel behandeld?", [["Als belast inkomen in box 1", "Uitkeringen die het inkomen vervangen, worden belast als inkomen; bij een werkgeversregeling vaak als loon."], ["Als belastingvrije schadevergoeding", "Een inkomensvervangende uitkering is geen onbelaste schadevergoeding."], ["Als vermogen in box 3", "Box 3 is niet van toepassing op periodieke inkomensvervangende uitkeringen."], ["Als inkomen uit aanmerkelijk belang in box 2", "Box 2 gaat over inkomsten uit een aanmerkelijk belang, zoals dividend."]], "1i.10"],
["Wat dekt een verzuimverzekering?", [["Het loondoorbetalingsrisico van de werkgever bij ziekte van werknemers", "Een verzuimverzekering vergoedt de werkgever (een deel van) het doorbetaalde loon tijdens de eerste twee ziektejaren."], ["De WIA-uitkering van de werknemer zodra de wachttijd van twee jaar is verstreken", "Na twee jaar is er geen verzuim meer maar WIA; daarvoor bestaan andere verzekeringen."], ["Het inkomensverlies van een zelfstandige bij ziekte", "Een zelfstandige verzekert zich met een AOV, niet met een verzuimverzekering."], ["De kosten van de werknemer voor medische behandeling", "Medische kosten vallen onder de zorgverzekering."]], "1g.10"],
["Henk (56) heeft een bakkerij met vijf werknemers en houdt daar zelf € 60.000 winst per jaar aan over. Hij is getrouwd en zijn zoon werkt mee in de zaak. Vorig jaar was een medewerker drie maanden ziek; dat kostte Henk veel geld, ook voor een uitzendkracht. Hij twijfelt of hij een verzuimverzekering nodig heeft. Welk argument weegt het zwaarst?", [["Eén langdurig zieke werknemer kost hem tot twee jaar loon, plus vaak een vervanger", "Voor een kleine werkgever kan één langdurig zieke werknemer een grote financiële last zijn; een verzuimverzekering spreidt dat risico."], ["Een verzuimverzekering is voor iedere werkgever wettelijk verplicht", "Een verzuimverzekering is niet verplicht; de werkgever kan het risico ook zelf dragen."], ["Zonder verzuimverzekering hoeft hij het loon niet door te betalen", "De loondoorbetalingsplicht geldt los van de vraag of de werkgever verzekerd is."], ["Een verzuimverzekering neemt de verplichtingen uit de Wet verbetering poortwachter over", "De re-integratieplichten blijven gelden, ook als de werkgever verzekerd is."]], "1b.1"],
["Wat houdt een stop-loss-verzuimverzekering in?", [["De werkgever draagt het verzuim zelf tot een maximumbedrag; de verzekeraar betaalt het meerdere", "Stop-loss beschermt de werkgever tegen uitschieters, terwijl hij het 'normale' verzuim zelf betaalt."], ["De verzekeraar vergoedt alle verzuimkosten vanaf de eerste dag", "Volledige vergoeding vanaf dag één is geen stop-loss, maar een uitgebreide dekking zonder eigen risico."], ["De verzekering stopt automatisch zodra een werknemer langer dan een jaar ziek is gebleven", "Stop-loss verwijst naar het begrenzen van het verlies, niet naar het stoppen van de dekking."], ["De werknemer betaalt de premie via zijn loon en de werkgever ontvangt de uitkeringen bij verzuim", "De premie van een verzuimverzekering is voor rekening van de werkgever."]], "1g.11"],
["Wat houdt eigenrisicodragerschap voor de WGA in?", [["De werkgever betaalt zelf maximaal tien jaar de WGA-uitkeringen en regelt de re-integratie", "De werkgever betaalt dan geen gedifferentieerde WGA-premie aan het UWV, maar draagt zelf het risico; dat wordt vaak verzekerd."], ["De werknemer betaalt zelf zijn WGA-uitkering", "Het eigenrisicodragerschap is een keuze van de werkgever en legt geen kosten bij de werknemer neer."], ["De werkgever draagt zelf het risico van de IVA-uitkeringen van zijn (ex-)werknemers", "Eigenrisicodragerschap gaat over de WGA; de IVA blijft bij het UWV."], ["De werkgever hoeft tijdens de eerste twee ziektejaren geen loon meer door te betalen aan zieke werknemers", "De loondoorbetalingsplicht in de eerste twee jaar blijft volledig bestaan."]], "1i.13"],
["Wat heeft een werkgever nodig om eigenrisicodrager voor de WGA te worden?", [["Een garantieverklaring van een verzekeraar of bank", "Met de garantieverklaring is gewaarborgd dat de uitkeringen doorlopen, ook als de werkgever niet meer kan betalen."], ["Een vergunning van de AFM", "De AFM verleent geen vergunningen voor eigenrisicodragerschap."], ["Schriftelijke toestemming van iedere individuele werknemer", "Individuele toestemming van werknemers is niet vereist."], ["Een minimumaantal van 100 werknemers", "Ook kleinere werkgevers kunnen eigenrisicodrager worden."]], "1f.9"],
["Wat dekt een woonlastenverzekering?", [["Een tijdelijke maandelijkse uitkering voor de woonlasten bij AO en/of werkloosheid", "Een woonlastenverzekering helpt de hypotheeklasten tijdelijk te betalen; de dekkingsomvang en duur verschillen per polis."], ["De volledige aflossing van de hypotheek bij werkloosheid", "Een woonlastenverzekering keert maandbedragen uit en lost de hypotheek niet af."], ["Schade aan de woning door brand of storm", "Dat is een opstalverzekering."], ["Het inkomensverlies bij arbeidsongeschiktheid, levenslang en tot het volledige bruto inkomen", "De uitkering is beperkt in duur en hoogte en dekt niet levenslang het inkomen."]], "1g.1"],
["Hoe wordt een woonlastenverzekering in de regel fiscaal behandeld?", [["De premie is niet aftrekbaar en de uitkering is onbelast", "Omdat de woonlastenverzekering geen inkomensvoorziening in fiscale zin is, is de premie niet aftrekbaar en de uitkering niet belast."], ["De premie is aftrekbaar en de uitkering belast in box 1", "Die behandeling geldt voor een AOV, niet voor een woonlastenverzekering."], ["De premie is aftrekbaar als hypotheekrente", "Een verzekeringspremie is geen rente op een eigenwoningschuld."], ["De uitkering valt in box 3", "Een woonlastenuitkering wordt niet als vermogen in box 3 belast."]], "1i.5"],
["Tom (35) is zelfstandig hovenier met € 38.000 winst per jaar; zijn partner Lisa werkt parttime als kapper. Zij hebben een koopwoning en een zoontje van twee. Tom heeft geen AOV en ziet een woonlastenverzekering als goedkoper alternatief. Zij vragen of een woonlastenverzekering een AOV kan vervangen. Wat is het juiste uitgangspunt?", [["Nee, die dekt alleen de woonlasten en tijdelijk; een AOV beschermt het inkomen langdurig", "Voor een zelfstandige zonder werknemersverzekeringen is een woonlastenverzekering hooguit een aanvulling, geen vervanging."], ["Ja, een woonlastenverzekering dekt hetzelfde inkomensrisico als een AOV", "De dekking verschilt sterk in omvang en duur."], ["Ja, omdat de woonlastenverzekering net als een AOV tot de AOW-leeftijd uitkeert", "Woonlastenverzekeringen keren in de regel beperkt in de tijd uit."], ["Nee, omdat een woonlastenverzekering alleen voor werknemers in loondienst kan worden gesloten", "Ook zelfstandigen kunnen een woonlastenverzekering sluiten, al dan niet met werkloosheidsdekking."]], "1g.1"],
["Mila de Wit (34) is zelfstandig fysiotherapeut en maakt € 48.000 winst per jaar. Zij woont samen en heeft een dochter van twee. Haar vader overleed jong aan een erfelijke hartspierziekte; vorig jaar liet zij een DNA-test doen, waaruit bleek dat zij de aanleg ook heeft. Zij heeft geen klachten en is niet onder behandeling of controle. Nu vraagt zij een AOV aan met een verzekerd bedrag dat onder de wettelijke vragengrens blijft. Moet zij de uitslag van haar DNA-test op de gezondheidsverklaring melden?", [["Nee, onder de vragengrens mag de verzekeraar niet naar de uitslag van erfelijkheidsonderzoek vragen", "Beneden de vragengrens zijn vragen naar de uitslag van erfelijkheidsonderzoek niet toegestaan, dus hoeft Mila die niet te melden. Vragen over eigen klachten en behandelingen moet zij wel eerlijk beantwoorden."], ["Ja, de mededelingsplicht geldt voor alle feiten die voor de verzekeraar van belang kunnen zijn", "De mededelingsplicht is begrensd: naar feiten waarnaar de verzekeraar wettelijk niet mag vragen, hoeft Mila niets te melden."], ["Ja, maar zij mag de uitslag alleen mondeling aan haar adviseur doorgeven", "Medische gegevens horen niet bij de adviseur thuis; bovendien hoeft de uitslag onder de vragengrens helemaal niet te worden gemeld."], ["Nee, een verzekeraar mag nooit naar erfelijkheidsonderzoek vragen, ook niet boven de vragengrens", "Dat gaat te ver: boven de vragengrens mag een verzekeraar in beginsel wel vragen naar de uitslag van een eerder gedaan erfelijkheidsonderzoek."]], "1h.8"],
["Mark Verbeek (46) is dga van een ICT-bedrijf en keert zichzelf via de bv € 120.000 per jaar aan salaris uit. Hij is getrouwd en heeft drie kinderen. Hij vraagt een AOV aan met een hoog verzekerd bedrag en een korte wachttijd. Omdat dat bedrag boven de keuringsgrens van de verzekeraar ligt, vraagt de verzekeraar naast de gezondheidsverklaring om een medische keuring. Mark vraagt of dat mag en wat er met de uitslag gebeurt. Wat is juist?", [["Dat mag; Mark mag de uitslag eerst zelf horen en kan doorgifte aan de verzekeraar tegenhouden", "Boven zijn keuringsgrens mag een verzekeraar een keuring verlangen. De Wet op de medische keuringen geeft Mark het recht de uitslag als eerste te vernemen en doorgifte te blokkeren; de verzekeraar kan de aanvraag dan wel weigeren."], ["Dat mag niet; bij een AOV volstaat volgens de wet altijd een gezondheidsverklaring", "Er is geen wettelijke regel dat een gezondheidsverklaring altijd volstaat; bij hoge bedragen is een aanvullende keuring gebruikelijk en toegestaan."], ["Dat mag; het keuringsrapport gaat ook naar zijn adviseur, die de acceptatie begeleidt", "Medische gegevens gaan naar de medisch adviseur van de verzekeraar en niet naar de adviseur van de klant."], ["Dat mag alleen als zijn eigen huisarts de keuring uitvoert", "Een behandelend arts keurt zijn eigen patiënt in de regel juist niet; de keuring wordt gedaan door een onafhankelijke keurend arts."]], "1h.8"],
["Iris Bakker (38) is zelfstandig makelaar en maakt € 70.000 winst per jaar. Zij is getrouwd en heeft twee kinderen op de basisschool. Haar vader kreeg op zijn 48e een hartinfarct en haar broer heeft een erfelijk verhoogd cholesterol. Op de gezondheidsverklaring voor haar AOV staat de vraag of bij ouders, broers of zussen hart- en vaatziekten voorkomen vóór een bepaalde leeftijd. Zij heeft zelf nooit een DNA-test gedaan. Moet zij de aandoeningen in haar familie melden?", [["Ja, als de gezondheidsverklaring daar uitdrukkelijk naar vraagt, moet zij de vraag naar waarheid beantwoorden", "De mededelingsplicht geldt voor de vragen die de verzekeraar stelt. Een vraag naar ziekten in de familie moet Iris eerlijk beantwoorden, ook al heeft zij zelf geen erfelijkheidsonderzoek gedaan."], ["Nee, gegevens over familieleden vallen nooit onder de mededelingsplicht van de aanvrager", "Vraagt de verzekeraar naar ziekten in de familie, dan valt het antwoord op die vraag wel onder de mededelingsplicht."], ["Nee, alleen de uitslag van een eigen DNA-test is relevant voor de verzekeraar", "De beperking onder de vragengrens gaat over de uitslag van erfelijkheidsonderzoek, niet over een gestelde vraag naar ziekten in de familie."], ["Alleen als haar familieleden daarvoor schriftelijk toestemming geven", "Iris beantwoordt de vraag met wat zij zelf weet; toestemming van familieleden is daarvoor geen voorwaarde."]], "1h.8"],
["Erwin Hendriks (52) is zelfstandig elektricien en maakt € 46.000 winst per jaar. Hij is getrouwd en zijn twee kinderen studeren. Op de gezondheidsverklaring voor zijn AOV meldt hij dat hij vorig jaar bij de cardioloog is geweest voor hartritmestoornissen. De verzekeraar wil meer weten voordat hij een acceptatiebeslissing neemt. Hoe mag de verzekeraar aan aanvullende medische informatie komen?", [["Zijn medisch adviseur mag met schriftelijke toestemming van Erwin feitelijke gegevens opvragen bij de cardioloog", "Aanvullende medische informatie loopt via de medisch adviseur van de verzekeraar en alleen met toestemming van de klant. De behandelaar verstrekt feitelijke gegevens en geeft geen oordeel over het verzekeringsrisico."], ["De acceptant mag zonder toestemming het volledige medische dossier bij de huisarts opvragen", "Zonder toestemming van Erwin mag geen medische informatie worden opgevraagd, en medische gegevens gaan niet naar de acceptant maar naar de medisch adviseur."], ["De adviseur van Erwin belt de cardioloog en geeft de informatie door aan de verzekeraar", "Een adviseur hoort geen medische informatie te verzamelen of door te geven; dat verloopt tussen artsen."], ["De cardioloog moet een oordeel geven over de vraag of Erwin verzekerbaar is", "Een behandelend arts geeft geen oordeel over verzekerbaarheid; dat beoordeelt de medisch adviseur van de verzekeraar."]], "1h.8"],
["Wat is het verschil tussen de vragengrens en een keuringsgrens bij een AOV?", [["De vragengrens is wettelijk vastgesteld; een keuringsgrens is acceptatiebeleid van de verzekeraar", "De vragengrens volgt uit de Wet op de medische keuringen en geldt voor alle verzekeraars. Boven welk bedrag of vanaf welke leeftijd een aanvullende keuring nodig is, bepaalt elke verzekeraar zelf in zijn acceptatierichtlijnen."], ["Beide grenzen worden jaarlijks door de AFM vastgesteld en gelden voor alle verzekeraars", "De AFM stelt deze grenzen niet vast; de vragengrens staat in regelgeving en keuringsgrenzen verschillen per verzekeraar."], ["Boven de vragengrens mag de verzekeraar geen gezondheidsverklaring meer vragen", "Boven de vragengrens mag een verzekeraar juist meer vragen, zoals naar de uitslag van een eerder erfelijkheidsonderzoek."], ["De keuringsgrens geldt alleen voor werknemers en de vragengrens alleen voor zelfstandigen", "Beide grenzen hangen samen met het verzekerde bedrag en de soort verzekering, niet met de vraag of iemand werknemer of zelfstandige is."]], "1h.8"],
["Mag een verzekeraar een aanvrager van een AOV verplichten een erfelijkheidstest (DNA-test) te laten doen?", [["Nee, hij mag niet verlangen dat de aanvrager een erfelijkheidsonderzoek ondergaat", "De Wet op de medische keuringen en de afspraken in het Moratorium Erfelijkheidsonderzoek sluiten zo'n verplichting uit, ook bij hoge verzekerde bedragen."], ["Ja, als het verzekerd bedrag boven de vragengrens ligt", "Boven de vragengrens mag de verzekeraar alleen vragen naar de uitslag van een eerder gedaan onderzoek; hij mag geen nieuwe test verlangen."], ["Ja, als er een erfelijke ziekte in de familie voorkomt", "Ook een erfelijke ziekte in de familie geeft de verzekeraar niet het recht een DNA-test te eisen."], ["Alleen als de medisch adviseur de uitslag geheimhoudt voor de acceptant", "Geheimhouding verandert niets aan het verbod om een erfelijkheidstest te verlangen."]], "1h.7"],
["Een adviseurskantoor krijgt van de AFM een bestuurlijke boete opgelegd. Welke weg staat voor het kantoor open?", [["Eerst bezwaar maken bij de AFM en daarna eventueel beroep instellen bij de bestuursrechter", "Tegen een besluit van de AFM staat eerst bezwaar bij de AFM zelf open. Daarna volgen beroep bij de rechtbank en hoger beroep bij het College van Beroep voor het bedrijfsleven."], ["Een klacht indienen bij het Kifid, dat de boete kan verlagen of vernietigen", "Het Kifid beslecht geschillen tussen klanten en financiële ondernemingen en kan geen boetes van de AFM toetsen."], ["Rechtstreeks in cassatie gaan bij de Hoge Raad", "Een AFM-besluit volgt de bestuursrechtelijke route van bezwaar en beroep; rechtstreeks naar de Hoge Raad is niet mogelijk."], ["Een verzoek indienen bij DNB om de boete opnieuw te beoordelen", "DNB en de AFM zijn elk bevoegd binnen hun eigen toezicht; DNB kan een AFM-boete niet herzien."]], "1a.3"],
["Wat is de betekenis van het maximumdagloon voor de werknemersverzekeringen?", [["Het is de bovengrens van het dagloon waarop WW-, ZW- en WIA-uitkeringen worden berekend", "Loon boven het maximumdagloon telt niet mee voor de uitkering, waardoor bij hogere inkomens een inkomensgat ontstaat. Het bedrag wordt periodiek aangepast."], ["Het is het minimumloon per dag dat een werkgever verplicht moet betalen", "Het minimumloon is een ondergrens voor het loon; het maximumdagloon begrenst juist de grondslag van de uitkering."], ["Het is het hoogste bedrag dat een AOV-verzekeraar mag uitkeren", "Een particuliere AOV kent eigen maximumbedragen; het maximumdagloon geldt voor de publieke werknemersverzekeringen."], ["Het is het maximale loon waarover een werknemer pensioen mag opbouwen", "Voor pensioenopbouw geldt een eigen fiscaal maximum; dat is iets anders dan het maximumdagloon."]], "1a.5"],
["Thijs Mulder (40) is zelfstandig installateur en maakt € 50.000 winst per jaar. Hij is getrouwd en heeft twee kinderen van zes en negen. Het gezin heeft een annuïteitenhypotheek en een overlijdensrisicoverzekering, en Thijs spaart via een lijfrenteverzekering voor zijn pensioen. Bij een AOV-advies vraagt hij waarom zijn adviseur ook naar die andere producten kijkt. Wat is het belangrijkste verband?", [["Bij arbeidsongeschiktheid lopen hypotheeklasten en premies door, tenzij een polis premievrijstelling bij AO kent", "Arbeidsongeschiktheid raakt alle vaste lasten. Daarom kijkt de adviseur of woonlasten en lopende premies betaalbaar blijven en of polissen premievrijstelling bij arbeidsongeschiktheid kennen."], ["Bij arbeidsongeschiktheid worden de hypotheek en de ORV automatisch premievrij gemaakt door de wet", "Er is geen wettelijke premievrijstelling; die bestaat alleen als zij in de polis is afgesproken."], ["Een AOV-uitkering wordt verrekend met de uitkering uit zijn ORV", "Een ORV keert uit bij overlijden en wordt niet verrekend met een AOV-uitkering."], ["Er is geen verband; een AOV-advies staat los van zijn andere financiële producten", "Een inkomensadvies kijkt juist naar het hele huishoudbudget, inclusief de lasten van andere producten."]], "1a.7"],
["Volgens de wet moet een werkgever een zieke werknemer ten minste 70% van het loon doorbetalen. Wat kan een cao hieraan veranderen?", [["Een cao kan een hogere loondoorbetaling afspreken, bijvoorbeeld 100% in het eerste ziektejaar", "Veel cao's vullen de wettelijke 70% aan. Dat verhoogt de loondoorbetalingsverplichting en dus het risico dat de werkgever eventueel verzekert."], ["Een cao kan de loondoorbetaling verlagen tot onder de 70% als de werkgever verzekerd is", "Van het wettelijke minimum kan niet ten nadele van de werknemer worden afgeweken."], ["Een cao kan bepalen dat de werkgever in het tweede ziektejaar niets hoeft te betalen", "Ook in het tweede jaar geldt ten minste de wettelijke 70%; een cao kan dat niet schrappen."], ["Een cao heeft geen invloed op de loondoorbetaling bij ziekte", "De cao is juist een belangrijke bron voor de hoogte van de loondoorbetalingsverplichting."]], "1b.4"],
["Een werkgever neemt iemand in dienst die onder de Participatiewet valt en door zijn beperking niet het volledige minimumloon kan verdienen. Welke regeling compenseert de werkgever voor het verschil tussen het loon en de loonwaarde?", [["Loonkostensubsidie via de gemeente", "Loonkostensubsidie op grond van de Participatiewet vult het verschil aan tussen het wettelijk minimumloon en de vastgestelde loonwaarde van de werknemer."], ["Een WGA-hiaatuitkering van het UWV", "Een WGA-hiaatuitkering komt van een verzekeraar bij arbeidsongeschiktheid en is geen subsidie voor de werkgever."], ["De transitievergoeding", "De transitievergoeding is een vergoeding voor de werknemer bij ontslag en heeft niets met loonwaarde te maken."], ["Een ZEZ-uitkering", "De ZEZ-uitkering is bedoeld voor zelfstandigen bij zwangerschap en bevalling."]], "1b.6"],
["Waarom is het Uniform Pensioenoverzicht (UPO) nuttig bij een inkomensadvies over arbeidsongeschiktheid?", [["Het toont of de pensioenregeling bij AO een uitkering of premievrije opbouw kent", "Uit het UPO blijkt welke voorzieningen de pensioenregeling bij arbeidsongeschiktheid biedt, zodat de adviseur geen dubbele of ontbrekende dekking adviseert."], ["Het toont het bedrag van de WIA-uitkering die het UWV zal toekennen", "Het UPO komt van de pensioenuitvoerder en bevat geen WIA-beslissing van het UWV."], ["Het vervangt de inkomensanalyse, omdat alle AO-risico's erop staan", "Het UPO toont alleen de pensioenregeling; andere voorzieningen en lasten blijven buiten beeld."], ["Het vermeldt de premie die de werknemer voor een AOV moet betalen", "Een particuliere AOV staat los van de pensioenregeling en komt niet op het UPO."]], "1b.7"],
["Hoe wordt de premie voor een particuliere AOV van een zelfstandige fiscaal behandeld?", [["Als aftrekbare uitgave voor inkomensvoorziening in box 1", "De premie voor een AOV is aftrekbaar in box 1; de uitkering is dan ook belast."], ["Als niet-aftrekbare consumptieve uitgave", "De AOV-premie is juist aftrekbaar."], ["Als kostenpost die alleen in box 2 aftrekbaar is", "Een zelfstandige met een eenmanszaak heeft geen box 2-inkomen uit zijn onderneming."], ["Als bezitting in box 3", "Een AOV heeft geen vermogenswaarde in box 3."]], "1i.5"],
["Hoe wordt een uitkering uit een particuliere AOV fiscaal behandeld?", [["Als belast inkomen in box 1", "Omdat de premie aftrekbaar is, wordt de uitkering als periodieke uitkering belast in box 1."], ["Als onbelaste schadevergoeding", "Een AOV-uitkering vervangt inkomen en is daarom belast."], ["Als vermogen in box 3", "Een periodieke inkomensvervangende uitkering valt niet in box 3."], ["Als belaste schenking", "Een verzekeringsuitkering is geen schenking."]], "1i.5"],
["Bart (40) is zelfstandig timmerman en maakt gemiddeld € 60.000 winst per jaar. Hij is getrouwd en heeft drie kinderen. Hij wil een AOV sluiten en heeft uitgerekend met welk netto besteedbaar inkomen het gezin rondkomt. Daarom wil hij het verzekerd bedrag op dat netto bedrag baseren. Waarom is dat onverstandig?", [["Omdat de uitkering belast is, moet hij het verzekerd bedrag bruto bepalen", "De AOV-uitkering wordt belast in box 1; wie op netto basis verzekert, houdt na belasting te weinig over."], ["Omdat de premie dan niet meer aftrekbaar is", "De aftrekbaarheid hangt niet af van de hoogte van het verzekerde bedrag."], ["Omdat verzekeraars alleen verzekerde bedragen accepteren die boven de gemiddelde winst liggen", "Verzekeraars beperken het verzekerd bedrag juist tot een deel van de winst."], ["Omdat een verzekerd bedrag op netto basis altijd tot oververzekering en dus premieverspilling leidt", "Een netto basis leidt eerder tot onderverzekering."]], "1i.5"],
["Welke combinatie van fiscale behandeling hoort bij een AOV, een ORV en een woonlastenverzekering?", [["AOV: aftrek en belaste uitkering; ORV en woonlasten: geen aftrek, uitkering niet in box 1", "Alleen de AOV is in box 1 een inkomensvoorziening; de ORV en de woonlastenverzekering kennen geen premieaftrek en geen box 1-heffing over de uitkering."], ["Alle drie: premie aftrekbaar in box 1 en uitkering belast als periodieke uitkering", "De ORV en de woonlastenverzekering kennen geen premieaftrek."], ["Alle drie: premie niet aftrekbaar en uitkering onbelast, omdat het risicoverzekeringen zijn", "Voor de AOV geldt juist premieaftrek en een belaste uitkering."], ["AOV en ORV: premie aftrekbaar en uitkering belast; woonlastenverzekering: geen van beide", "De ORV-premie is niet aftrekbaar."]], "1i.5"],
["Welke risico's horen in elk geval aan bod te komen in een inkomensanalyse bij een hypotheekadvies?", [["Arbeidsongeschiktheid, werkloosheid, overlijden en pensionering", "Een volledige inkomensanalyse laat zien wat de financiële gevolgen van deze gebeurtenissen zijn voor de betaalbaarheid van de woonlasten."], ["Alleen overlijden van de hoofdkostwinner", "Een analyse die zich alleen op overlijden richt, is niet volledig."], ["Alleen de rentestand bij het einde van de rentevaste periode", "Renterisico is relevant, maar is geen inkomensrisico zoals AO of werkloosheid."], ["Alleen de waardeontwikkeling van de woning", "De woningwaarde is relevant voor de financiering, maar niet voor de inkomensanalyse."]], "1d.2"],
["Linda (32) is vast in dienst als marketingmedewerker en verdient € 3.500 bruto per maand. Zij woont samen en heeft net een huis gekocht. Na de langdurige ziekte van een collega is zij bang voor inkomensverlies als zij zelf ziek wordt. Zij vraagt haar adviseur om een AOV. Wat doet de adviseur eerst?", [["Nagaan welke voorzieningen zij al heeft, zoals loondoorbetaling, WIA en WGA-hiaatdekking", "Pas als de bestaande voorzieningen bekend zijn, kan de adviseur bepalen of er een resterend inkomensrisico is dat aanvullende dekking rechtvaardigt."], ["Direct een AOV met de kortste wachttijd adviseren, zodat zij vanaf dag één gedekt is", "Zonder inventarisatie van bestaande dekkingen kan het advies leiden tot dubbele of onnodige verzekering."], ["Haar adviseren haar vaste contract op te zeggen", "Dit is geen verantwoord advies en lost het inkomensrisico niet op."], ["Een woonlastenverzekering adviseren in plaats van een uitgebreide analyse van haar inkomen", "Ook een woonlastenverzekering adviseren zonder analyse is in strijd met de zorgvuldigheid."]], "1d.2"],
["Wat verplicht de Europese richtlijn verzekeringsdistributie (IDD) de distributeur vóór het sluiten van een verzekering?", [["Op basis van klantinformatie diens wensen en behoeften vaststellen", "De IDD vereist dat elk aangeboden verzekeringsproduct aansluit bij de wensen en behoeften van de klant."], ["Altijd een medische keuring laten uitvoeren", "Of een keuring nodig is, hangt af van het product en de acceptatiecriteria, niet van de IDD."], ["Altijd het goedkoopste product op de markt adviseren, ongeacht de dekking", "De IDD schrijft geen goedkoopste product voor; het gaat om passendheid."], ["De verzekering vooraf laten goedkeuren door de AFM", "De AFM keurt individuele verzekeringen niet vooraf goed."]], "1a.1"],
["Welke informatie moet een verzekeringsdistributeur onder de IDD in elk geval aan de klant geven?", [["De aard van de beloning die hij voor zijn dienstverlening ontvangt", "De IDD verlangt dat de klant weet of de distributeur bijvoorbeeld een fee of provisie ontvangt."], ["De winstcijfers van de verzekeraar over de afgelopen tien jaar", "Winstcijfers van de verzekeraar zijn geen verplichte klantinformatie onder de IDD."], ["De persoonlijke inkomsten van de adviseur", "Het gaat om de aard van de beloning voor de dienstverlening, niet om het privé-inkomen."], ["De namen van alle andere klanten met hetzelfde product", "Dat zou in strijd zijn met de privacy van die klanten."]], "1h.5"],
["Sophie (29) is zelfstandig grafisch ontwerper en maakt € 32.000 winst per jaar. Zij woont alleen in een huurwoning. Haar adviseur raadt haar een AOV aan met beroepsdekking en de kortste wachttijd, waarvan de premie een groot deel van haar besteedbaar inkomen opslokt. Na een jaar kan zij de premie niet meer opbrengen. Wat is het belangrijkste probleem?", [["Het advies is niet passend, omdat het de financiële positie van de klant negeert", "De zorgplicht vereist dat een advies ook betaalbaar is; alternatieven zoals een langere wachttijd of een lager verzekerd bedrag hadden moeten worden afgewogen."], ["Een beroepsdekking mag volgens de Wft nooit aan zelfstandigen worden geadviseerd", "Een beroepsdekking kan juist passend zijn; het probleem is de betaalbaarheid."], ["De adviseur had een woonlastenverzekering moeten adviseren", "Dat lost het probleem van de onbetaalbare inkomensdekking niet op."], ["Er is geen probleem, zolang de klant het adviesrapport en de offerte heeft ondertekend", "Een handtekening ontslaat de adviseur niet van zijn zorgplicht."]], "1a.1"],
["Hoe moet een adviseur omgaan met de gezondheidsverklaring van een klant bij een AOV- of ORV-aanvraag?", [["De klant vult hem zelf in; hij gaat rechtstreeks naar de medisch adviseur", "Gezondheidsgegevens zijn bijzondere persoonsgegevens; de adviseur hoort geen kennis te nemen van de medische details."], ["De adviseur vult de verklaring namens de klant in om fouten en vertraging te voorkomen", "Daarmee neemt de adviseur kennis van gevoelige gegevens en loopt hij het risico op onjuiste opgaven."], ["De adviseur bewaart een kopie in het klantdossier", "Medische gegevens horen niet in het dossier van het advieskantoor."], ["De verklaring wordt via de acceptant van de verzekeraar openbaar gedeeld", "Gezondheidsgegevens worden alleen door de medische dienst van de verzekeraar beoordeeld."]], "4b.2"],
["Wat zijn gezondheidsgegevens volgens de AVG?", [["Bijzondere persoonsgegevens, met een verwerkingsverbod tenzij een uitzondering geldt", "Voor gezondheidsgegevens gelden strengere regels dan voor gewone persoonsgegevens."], ["Gewone persoonsgegevens, zoals naam en adres, die vrij mogen worden verwerkt", "Gezondheidsgegevens zijn juist een bijzondere categorie."], ["Openbare gegevens die de verzekeraar vrij mag delen met andere financiële instellingen", "Gezondheidsgegevens zijn juist zeer gevoelig en niet openbaar."], ["Gegevens die alleen onder de Wwft vallen en na vijf jaar moeten worden vernietigd", "De Wwft gaat over witwassen; de bescherming van gezondheidsgegevens valt onder de AVG."]], "1a.6"],
["Welk recht heeft een keurling op grond van de Wet op de medische keuringen bij een keuring voor een verzekering?", [["Het recht om de uitslag eerst zelf te horen en doorgifte aan de verzekeraar te blokkeren", "Met dit recht houdt de keurling zelf de regie over de uitslag; de verzekeraar kan de aanvraag dan wel weigeren."], ["Het recht om de premie zelf vast te stellen", "De premie wordt door de verzekeraar bepaald."], ["Het recht om de keuring door zijn eigen huisarts als keurend arts te laten uitvoeren, op kosten van de verzekeraar", "Een behandelend arts mag in de regel niet als keurend arts optreden, en de keurling bepaalt de kosten van de keuring niet."], ["Het recht op een gegarandeerde acceptatie tegen standaardpremie na de keuring", "Een keuring garandeert geen acceptatie."]], "1a.4"],
["Wat is de functie van de 'vragengrens' bij verzekeringskeuringen?", [["Onder die grens mag de verzekeraar niet vragen naar erfelijkheidsonderzoek en de uitslag", "De vragengrens beschermt mensen met een (mogelijk) erfelijk risico die een verzekering tot een bepaald bedrag willen sluiten."], ["Boven de vragengrens mag de verzekeraar helemaal geen gezondheidsvragen meer stellen aan de aanvrager", "Het is juist andersom: boven de grens zijn meer vragen toegestaan."], ["De vragengrens bepaalt het maximum verzekerd bedrag in een AOV", "De vragengrens beperkt welke vragen mogen worden gesteld, niet het maximum verzekerd bedrag."], ["De vragengrens geldt alleen voor de Wwft-identificatie", "De vragengrens hoort bij medische keuringen, niet bij de Wwft."]], "1h.8"],
["Een installatiebedrijf met twintig werknemers wordt via een activatransactie overgenomen door een andere onderneming. Er is sprake van overgang van onderneming. Wat geldt voor de werknemers?", [["Zij gaan met hun arbeidsvoorwaarden over, met onder voorwaarden een uitzondering voor pensioen", "Bij overgang van onderneming gaan de rechten en plichten uit de arbeidsovereenkomsten van rechtswege over. De aanvullende pensioenregeling gaat onder voorwaarden niet mee, bijvoorbeeld als de verkrijger een eigen regeling heeft of aanbiedt."], ["Hun arbeidsovereenkomsten eindigen en zij moeten opnieuw solliciteren", "De arbeidsovereenkomsten lopen juist door bij de nieuwe werkgever."], ["Zij gaan over, maar de nieuwe eigenaar mag direct alle arbeidsvoorwaarden verlagen", "De arbeidsvoorwaarden gaan mee; de verkrijger kan ze niet eenzijdig verslechteren vanwege de overgang."], ["Alleen werknemers met een vast contract van langer dan vijf jaar gaan over", "Alle werknemers die bij de overgedragen onderneming werken, gaan over, ongeacht hun diensttijd."]], "1c.2"],
["Een timmerman in loondienst valt van een steiger zonder valbeveiliging en raakt langdurig arbeidsongeschikt. Is de werkgever aansprakelijk voor de schade van de werknemer?", [["In beginsel wel, tenzij hij aantoont dat hij aan zijn zorgplicht voor veilig werken heeft voldaan", "De werkgever is aansprakelijk voor schade door een arbeidsongeval, tenzij hij zijn zorgplicht is nagekomen of de schade in belangrijke mate komt door opzet of bewuste roekeloosheid van de werknemer."], ["Alleen als de werknemer kan bewijzen dat de werkgever opzettelijk heeft gehandeld", "De werknemer hoeft geen opzet te bewijzen; de werkgever moet aantonen dat hij voldoende zorg heeft betracht."], ["Nooit, omdat de WIA en de loondoorbetaling alle schade dekken", "Sociale uitkeringen dekken niet alle schade, zoals smartengeld en inkomensverlies boven het uitkeringsniveau."], ["Alleen als de werkgever een aansprakelijkheidsverzekering heeft", "Aansprakelijkheid hangt niet af van een verzekering; een verzekering dekt hooguit de financiële gevolgen ervan."]], "1d.4"],
["Hoe vaak moeten werkgever en werknemer volgens de Wet verbetering poortwachter de voortgang van het plan van aanpak ten minste bespreken?", [["Ten minste eens per zes weken", "Poortwachter schrijft een regelmatige evaluatie voor, minimaal eens per zes weken, zodat het plan zo nodig tijdig wordt bijgesteld."], ["Eens per kwartaal, tegelijk met de verzuimrapportage", "Een kwartaal is te lang; de wet vraagt een frequentere evaluatie van het re-integratieplan."], ["Alleen bij de eerstejaarsevaluatie en de WIA-aanvraag", "Dat zijn wel vaste momenten, maar daartussen moet de voortgang ook periodiek worden besproken."], ["Elke twee weken, op voorschrift van het UWV", "Het UWV schrijft geen tweewekelijkse bespreking voor; de wettelijke norm is minimaal eens per zes weken."]], "1i.9"],
["Wat is de eerstejaarsevaluatie bij langdurig verzuim?", [["Een vast moment rond week 52 om het re-integratiedoel voor jaar twee te bepalen", "Werkgever en werknemer kijken na ongeveer een jaar terug en leggen vast welk re-integratiedoel in het tweede jaar wordt nagestreefd."], ["Een keuring door het UWV die bepaalt of de loondoorbetaling in het tweede jaar doorloopt", "Het UWV keurt pas bij de WIA-aanvraag; de eerstejaarsevaluatie is een afspraak tussen werkgever en werknemer."], ["Het moment waarop het opzegverbod bij ziekte vervalt", "Het opzegverbod geldt in beginsel gedurende de eerste twee ziektejaren, niet alleen het eerste jaar."], ["De eerste beoordeling door de verzuimverzekeraar of hij uitkeert", "Een verzuimverzekeraar beoordeelt dekking volgens de polis; de eerstejaarsevaluatie is een Poortwachter-stap."]], "1i.9"],
["Wie wijst bij langdurig verzuim de casemanager aan?", [["De werkgever", "De werkgever is verantwoordelijk voor de re-integratie en wijst een casemanager aan die het proces bewaakt; dat kan ook de bedrijfsarts zijn."], ["Het UWV, zodra de ziekmelding in week 42 binnen is", "Het UWV beoordeelt de re-integratie achteraf, maar wijst geen casemanager aan."], ["De werknemer zelf, uit een lijst van de arbodienst", "De regie ligt bij de werkgever; de werknemer kiest de casemanager niet."], ["De verzuimverzekeraar, als voorwaarde voor dekking", "Een verzekeraar kan hulp bieden, maar de wettelijke verantwoordelijkheid voor het aanwijzen ligt bij de werkgever."]], "1i.9"],
["Wat is het re-integratieverslag?", [["Het dossier over het verloop van de re-integratie dat met de WIA-aanvraag naar het UWV gaat", "Met het re-integratieverslag laten werkgever en werknemer zien wat zij in twee jaar hebben gedaan; het UWV toetst daarmee hun inspanningen."], ["Een medisch rapport van de bedrijfsarts dat alleen de werknemer zelf te zien krijgt over zijn ziekte", "Het verslag bevat wel het oordeel van de bedrijfsarts, maar is een gezamenlijk dossier dat naar het UWV gaat."], ["Een jaarlijkse rapportage van de werkgever aan de verzuimverzekeraar", "Verzekeraars kunnen rapportages vragen, maar het re-integratieverslag is een wettelijk document voor het UWV."], ["Het verslag van de keuring door de verzekeringsarts van het UWV", "De keuring door het UWV volgt juist ná het indienen van het re-integratieverslag."]], "1k.14"],
["Erik (37) werkt als kok in een restaurant en verdient € 2.700 bruto per maand. Hij is getrouwd en heeft een dochter van vier. Hij is vier weken ziek door een longontsteking, werkt daarna drie weken volledig en valt dan uit met rugklachten. Zijn werkgever vraagt zich af of de termijn voor loondoorbetaling opnieuw begint. Hoe tellen deze periodes voor de loondoorbetaling?", [["Ze worden samengeteld, omdat de onderbreking korter dan vier weken is", "Ziekteperiodes die elkaar met minder dan vier weken onderbreking opvolgen, worden samengeteld, ongeacht de oorzaak."], ["Er start een nieuwe termijn van 104 weken, omdat de klachten anders zijn", "De oorzaak doet voor de samentelling niet ter zake; alleen de duur van de onderbreking telt."], ["Ze worden alleen samengeteld als de bedrijfsarts dezelfde oorzaak vaststelt", "Samentelling hangt niet af van dezelfde oorzaak, maar van een onderbreking korter dan vier weken."], ["De eerste periode vervalt, omdat Erik volledig hersteld is gemeld", "Een herstelmelding verbreekt de keten pas als de werknemer ten minste vier weken weer werkt."]], "1i.8"],
["Gijs (52) is productieleider bij een metaalbedrijf en verdient € 4.300 bruto per maand. Hij is getrouwd en heeft twee studerende kinderen. Na een burn-out is hij bijna twee jaar ziek, maar hij werkt alweer een deel van zijn uren en knapt snel op. Zijn werkgever en hij verwachten dat volledige terugkeer binnen enkele maanden lukt. Wat kunnen zij doen?", [["Samen het UWV vragen de wachttijd te verlengen, waarbij het loon wordt doorbetaald", "Werkgever en werknemer kunnen gezamenlijk om vrijwillige verlenging van de loondoorbetaling vragen, zodat de WIA-beoordeling wordt uitgesteld."], ["De werkgever kan zonder instemming van de werknemer eenzijdig besluiten de WIA-aanvraag uit te stellen", "Uitstel kan alleen op gezamenlijk verzoek van werkgever en werknemer; eenzijdig uitstellen is niet mogelijk."], ["De werknemer vraagt tijdelijk WW aan tot hij weer hersteld is", "Een zieke werknemer is niet beschikbaar voor werk en heeft daarom geen recht op WW."], ["Niets, want na 104 weken eindigt de loondoorbetaling altijd", "De wet biedt juist de mogelijkheid van een vrijwillige verlenging."]], "1i.9"],
["Hoe lang moet een werkgever het loon doorbetalen aan een zieke werknemer die de AOW-leeftijd al heeft bereikt?", [["Maximaal 13 weken", "Voor werknemers die de AOW-leeftijd hebben bereikt, geldt een kortere loondoorbetalingsperiode van maximaal 13 weken."], ["Maximaal 104 weken, net als bij andere werknemers", "Voor AOW-gerechtigde werknemers is de loondoorbetalingsplicht juist ingekort."], ["Helemaal niet, omdat de werknemer al AOW ontvangt", "Ook een AOW-gerechtigde werknemer heeft recht op loondoorbetaling, alleen voor een kortere periode."], ["Maximaal 52 weken, daarna neemt de Ziektewet het over", "Die termijn bestaat niet voor AOW-gerechtigden; de periode is korter."]], "1g.2"],
["Wat mag een werkgever een werknemer vragen bij een ziekmelding?", [["Hoe lang het verzuim naar verwachting duurt en waar de werknemer bereikbaar is", "De werkgever mag vragen wat nodig is voor de organisatie van het werk, zoals de verwachte duur, het verblijfadres en lopende afspraken."], ["Wat de aard en oorzaak van de ziekte zijn, zodat hij gericht passend werk kan zoeken", "De diagnose is een gezondheidsgegeven; daarover beoordeelt de bedrijfsarts, niet de werkgever."], ["Welke medicijnen de werknemer gebruikt en in welke dosis", "Medicijngebruik is medische informatie die de werkgever niet mag vragen of vastleggen."], ["Toestemming om de huisarts te bellen voor een ziektebeeld", "Een werkgever mag geen medische informatie bij de behandelaar opvragen; dat loopt via de bedrijfsarts."]], "1a.6"],
["Joost (34) is accountmanager bij een uitzendbureau en verdient € 3.900 bruto per maand. Hij woont samen en heeft een baby. Op weg naar een klant wordt hij aangereden door een automobilist die door rood rijdt en daarvoor aansprakelijk is. Joost is maandenlang arbeidsongeschikt en zijn werkgever betaalt zijn loon door. Wat kan de werkgever doen met de doorbetaalde loonkosten?", [["Die verhalen op de aansprakelijke partij en diens verzekeraar", "Een werkgever heeft een regresrecht voor het doorbetaalde loon als een derde aansprakelijk is voor de arbeidsongeschiktheid."], ["Niets, want loondoorbetaling bij ziekte is altijd werkgeversrisico", "Loondoorbetaling is wel zijn verplichting, maar bij aansprakelijkheid van een derde kan hij de schade verhalen."], ["Alleen verhalen als hij een verzuimverzekering heeft", "Het regresrecht hangt niet af van een verzuimverzekering; de verzekeraar kan wel namens hem verhalen."], ["De loonkosten terugvragen bij het UWV", "Het UWV vergoedt geen loonkosten bij een verkeersongeval; verhaal loopt via de aansprakelijke partij."]], "1k.7"],
["Wat is een werkgever op grond van de Arbowet verplicht bij de begeleiding van zieke werknemers?", [["Zich laten bijstaan door een bedrijfsarts of arbodienst op basis van een contract", "De Arbowet verplicht de werkgever deskundige ondersteuning bij verzuim te regelen en dit vast te leggen in een (basis)contract."], ["Een verzuimverzekering sluiten die het doorbetaalde loon van alle zieke werknemers dekt", "Een verzuimverzekering is vrijwillig; de werkgever mag het risico ook zelf dragen."], ["Eigenrisicodrager voor de Ziektewet worden voor zijn flexwerkers", "Eigenrisicodragerschap is een keuze en geen verplichting uit de Arbowet."], ["Elke ziekmelding binnen een week ook bij het UWV melden", "Bij het UWV meldt de werkgever pas langdurig verzuim, in de 42e ziekteweek."]], "1d.1"],
["Waarom heeft een middelgrote of grote werkgever die publiek verzekerd is er financieel belang bij dat weinig ex-werknemers in de WGA en de ZW instromen?", [["Zijn premie voor de Werkhervattingskas hangt mede af van die eigen instroom", "Voor middelgrote en grote werkgevers is de Whk-premie gedifferentieerd: meer instroom leidt tot een hogere premie."], ["Het UWV verhaalt de WGA- en ZW-uitkeringen direct en volledig op de laatste werkgever", "Bij publieke verzekering betaalt het UWV de uitkering; de werkgever merkt het via de premie, niet via direct verhaal."], ["Hij verliest anders zijn recht op een contract met een arbodienst", "Er bestaat geen sanctie die het arbocontract koppelt aan de instroom in WGA of ZW."], ["De AFM legt hem anders een boete op wegens slecht verzuimbeleid", "De AFM houdt toezicht op financiële markten, niet op het verzuimbeleid van werkgevers."]], "1d.1"],
["Wat kan een werkgever doen als een zieke werknemer zich niet aan redelijke controlevoorschriften houdt, zoals het niet verschijnen op het spreekuur van de bedrijfsarts?", [["Het loon opschorten tot de werknemer de voorschriften alsnog nakomt", "Bij het niet naleven van redelijke controlevoorschriften mag de werkgever het loon opschorten; na nakoming wordt het alsnog betaald."], ["De werknemer direct op staande voet ontslaan", "Ontslag op staande voet is een zwaar middel; het niet opvolgen van controlevoorschriften leidt in eerste instantie tot opschorting."], ["Het loon definitief stopzetten over de hele resterende ziekteperiode", "Opschorten is iets anders dan stopzetten: bij opschorting krijgt de werknemer het loon later alsnog."], ["Het UWV vragen de Ziektewet-uitkering in te houden", "Een werknemer in dienst krijgt loon van de werkgever, geen ZW-uitkering; het UWV is hier niet aan zet."]], "1k.5"],
["Hoe hoog is een Ziektewet-uitkering in de regel?", [["70% van het (gemaximeerde) dagloon", "De standaard ZW-uitkering bedraagt 70% van het dagloon, dat aan een maximum is gebonden."], ["100% van het loon in het eerste ziektejaar", "100% geldt alleen in bijzondere situaties, zoals ziekte door zwangerschap; de hoofdregel is 70%."], ["75% de eerste twee maanden, daarna 70%", "Die opbouw kent de WW en de loongerelateerde WGA, niet de Ziektewet."], ["Een vast percentage van het minimumloon", "De ZW-uitkering is loongerelateerd en gebaseerd op het eigen dagloon."]], "1i.2"],
["Anouk (30) is juridisch medewerker bij een notariskantoor en verdient € 3.200 bruto per maand. Zij is getrouwd en verwacht haar eerste kind. Drie maanden vóór haar zwangerschapsverlof wordt zij ziek door ernstige zwangerschapsklachten. Haar werkgever wil weten welke kosten hij moet dragen. Wat is de positie van haar werkgever?", [["Hij betaalt het loon door en kan bij het UWV een ZW-uitkering voor haar aanvragen", "Bij ziekte door zwangerschap geldt een vangnet: de werkgever betaalt door en ontvangt een ZW-uitkering van het UWV ter compensatie."], ["Hij hoeft geen loon te betalen, omdat zwangerschap geen ziekte is", "Ziekte als gevolg van zwangerschap is wel ziekte; de werkgever moet het loon doorbetalen."], ["Haar zwangerschapsverlof gaat direct bij de ziekmelding in, ongeacht de uitgerekende datum", "Het verlof start rond een vaste periode vóór de uitgerekende datum, niet automatisch bij ziekte."], ["Hij draagt de loonkosten volledig zelf, zonder enige compensatie", "Juist om werkgevers te ontzien geldt bij zwangerschapsgerelateerde ziekte de ZW-vangnetregeling."]], "1b.5"],
["Wie verstrekt de uitkering tijdens het zwangerschaps- en bevallingsverlof van een werkneemster?", [["Het UWV, op grond van de Wet arbeid en zorg; vaak via de werkgever uitbetaald", "De WAZO-uitkering komt van het UWV; de werkgever vraagt die meestal aan en betaalt die door via het loon."], ["De werkgever, zonder dat hij daarvoor gecompenseerd wordt", "De werkgever betaalt vaak uit, maar ontvangt daarvoor de uitkering van het UWV."], ["De Sociale Verzekeringsbank, omdat het verlofgeld onder de volksverzekeringen valt", "De SVB voert volksverzekeringen uit; het verlofgeld is een werknemersregeling via het UWV."], ["De zorgverzekeraar, als onderdeel van de kraamzorg", "De zorgverzekeraar vergoedt zorg, geen inkomen tijdens verlof."]], "1b.5"],
["Wat houdt de no-riskpolis in?", [["Bij ziekte van een werknemer met een arbeidsbeperking krijgt de werkgever ZW", "De no-riskpolis verlaagt het risico om iemand met een arbeidsbeperking in dienst te nemen: bij ziekte compenseert het UWV de loonkosten."], ["Een verzuimverzekering zonder eigen risico, speciaal ontwikkeld voor kleine werkgevers", "De no-riskpolis is een publieke regeling van het UWV en geen particuliere verzuimverzekering."], ["Een extra ontslagbescherming voor werknemers met een chronische ziekte", "De regeling geeft geen ontslagbescherming, maar een loonkostencompensatie voor de werkgever."], ["Een premievrije AOV voor jonggehandicapten die gaan ondernemen", "Een no-riskpolis betreft werknemers in dienstbetrekking, geen AOV voor ondernemers."]], "1b.6"],
["Sven (45) is projectleider bij een ingenieursbureau en verdient € 4.800 bruto per maand. Hij is getrouwd en heeft drie kinderen. Hij staat een nier af aan zijn broer en is na de operatie zes weken ziek. Zijn werkgever vraagt of hij die loonkosten zelf moet dragen. Wat geldt?", [["De werkgever betaalt door en kan via het UWV-vangnet ZW krijgen", "Voor ziekte door orgaandonatie geldt een vangnetregeling in de Ziektewet; de werkgever krijgt compensatie."], ["Sven heeft geen recht op loon, want hij koos zelf vrijwillig voor de operatie", "Ook bij orgaandonatie is sprake van ziekte waarvoor het loon wordt doorbetaald."], ["Sven krijgt direct een WIA-uitkering voor de herstelperiode", "De WIA komt pas na een wachttijd van 104 weken in beeld, niet bij kortdurend verzuim."], ["De zorgverzekeraar van de broer vergoedt Svens loon", "De zorgverzekeraar vergoedt de medische kosten, niet het loon van de donor."]], "1b.5"],
["Ingrid (54) was teamleider bij een callcenter en verdiende € 3.200 bruto per maand. Zij is alleenstaand. Na een reorganisatie ontvangt zij sinds twee maanden een WW-uitkering. Dan wordt zij ziek en moet zij een langdurige behandeling ondergaan. Wat gebeurt er met haar uitkering?", [["De eerste 13 weken loopt de WW door; daarna kan zij een ZW-uitkering krijgen", "Bij ziekte tijdens de WW wordt de WW nog 13 weken betaald; duurt de ziekte langer, dan volgt de Ziektewet."], ["De WW stopt direct en de Ziektewet gaat vanaf de eerste dag in", "Er geldt eerst een periode waarin de WW doorloopt; pas daarna volgt de ZW."], ["Zij heeft geen uitkering meer, want zij is niet beschikbaar", "Er is wel een regeling: eerst WW, daarna ZW."], ["De WW loopt gewoon de volledige resterende duur door, ongeacht hoe lang de ziekte duurt", "Na 13 weken ziekte stopt de WW en gaat zij over naar de Ziektewet."]], "1i.2"],
["Wie dient de WIA-aanvraag in?", [["De werknemer, samen met het re-integratieverslag", "De werknemer vraagt de WIA aan; het re-integratieverslag dat hij met de werkgever opstelt, hoort bij de aanvraag."], ["De werkgever, zonder betrokkenheid van de werknemer", "De werkgever levert zijn deel van het verslag, maar de aanvraag zelf doet de werknemer."], ["De bedrijfsarts, zodra de wachttijd bijna voorbij is", "De bedrijfsarts geeft medisch advies, maar dient geen uitkeringsaanvraag in."], ["Niemand; het UWV start de beoordeling automatisch", "Het UWV stuurt informatie, maar zonder aanvraag van de werknemer volgt geen beoordeling."]], "1k.1"],
["Welke rolverdeling geldt bij de WIA-beoordeling door het UWV?", [["De verzekeringsarts stelt de beperkingen vast; de arbeidsdeskundige berekent het verlies aan verdiencapaciteit", "Eerst bepaalt de verzekeringsarts wat iemand medisch nog kan; daarna zoekt de arbeidsdeskundige passende functies en berekent het arbeidsongeschiktheidspercentage."], ["De arbeidsdeskundige stelt de beperkingen vast; de verzekeringsarts berekent het arbeidsongeschiktheidspercentage", "De rollen zijn hier omgedraaid: de medische beoordeling hoort bij de verzekeringsarts."], ["De bedrijfsarts van de werkgever bepaalt het percentage en het UWV neemt dat over", "Het UWV beoordeelt zelfstandig; de bedrijfsarts heeft daarin geen beslissende rol."], ["Beide adviseren alleen; de werkgever neemt het besluit", "Het besluit over de WIA neemt het UWV, niet de werkgever."]], "1k.2"],
["Wat betekent 'duurzaam' arbeidsongeschikt voor de IVA?", [["Er is geen of slechts een geringe kans op herstel", "Voor de IVA moet iemand niet alleen volledig, maar ook duurzaam arbeidsongeschikt zijn: herstel is niet of nauwelijks te verwachten."], ["De werknemer is al ten minste twee jaar ziek", "Twee jaar ziekte is de wachttijd voor de WIA en zegt nog niets over de kans op herstel."], ["De werknemer is ten minste 80% arbeidsongeschikt", "80% of meer betekent volledig arbeidsongeschikt; duurzaamheid is een aparte voorwaarde."], ["De ziekte duurt naar verwachting nog minimaal een jaar", "Duurzaamheid gaat over het uitblijven van herstel op lange termijn, niet over een termijn van een jaar."]], "1i.11"],
["Youssef (36) werkte als zelfstandig ICT-consultant toen hij een AOV sloot met een premie voor kantoorwerk. Hij is getrouwd en heeft een zoon van vier. Een jaar geleden is hij overgestapt naar werk als zelfstandig dakdekker, waarmee hij € 50.000 winst per jaar maakt, maar die beroepswijziging heeft hij niet aan de verzekeraar gemeld. Na een val van een dak meldt hij zich arbeidsongeschikt. Wat kan de verzekeraar in de regel doen?", [["De uitkering verlagen naar verhouding van de betaalde tot de juiste premie", "AOV-voorwaarden kennen bij een niet gemelde beroepswijziging meestal een evenredige vermindering van de uitkering, omdat te weinig premie is betaald voor het werkelijke risico."], ["Volledig uitkeren, omdat de beroepswijziging niets met de claim te maken heeft", "De beroepswijziging verhoogt juist het risico; de te lage premie heeft gevolgen voor de uitkering."], ["Youssef doorverwijzen naar het UWV voor een WIA-uitkering", "Als zelfstandige is Youssef niet verzekerd voor de WIA."], ["De uitkering verhogen, omdat dakdekken een zwaarder beroep is", "Een zwaarder beroep leidt tot een hogere premie, niet tot een hogere uitkering als die premie niet is betaald."]], "1f.7"],
["Hoe hoog is de loongerelateerde WGA-uitkering voor iemand die niet werkt?", [["De eerste twee maanden 75% van het dagloon, daarna 70%", "In de loongerelateerde fase krijgt de uitkeringsgerechtigde eerst 75% en na twee maanden 70% van het (gemaximeerde) dagloon."], ["Gedurende de hele loongerelateerde fase 75% van het dagloon", "75% geldt alleen de eerste twee maanden; daarna daalt het naar 70%."], ["Een percentage van het minimumloon, afhankelijk van de mate van AO", "Dat is de systematiek van de vervolguitkering, niet van de loongerelateerde fase."], ["100% van het maatmaninkomen tot het maximumdagloon", "Een volledige vervanging van het inkomen kent de WGA niet."]], "1i.12"],
["Hoe wordt de WGA-loonaanvullingsuitkering berekend?", [["70% van het verschil tussen maatmaninkomen en restverdiencapaciteit", "De loonaanvulling vult aan op basis van wat iemand theoretisch nog kan verdienen, niet op basis van wat hij werkelijk verdient."], ["70% van het volledige maatmaninkomen", "De uitkering vervangt alleen een deel van het verlies, niet het hele vroegere inkomen."], ["70% van het verschil tussen maatmaninkomen en het werkelijk verdiende loon", "Bij de loonaanvulling telt de restverdiencapaciteit, niet het werkelijk verdiende loon."], ["Een vast percentage van het minimumloon", "Een uitkering op basis van het minimumloon is de vervolguitkering, niet de loonaanvulling."]], "1i.12"],
["Wim (49) is vrachtwagenchauffeur en verdiende € 3.000 bruto per maand. Hij is getrouwd en heeft twee tieners. Na twee jaar ziekte door een rugaandoening kreeg hij geen WIA, omdat hij 30% arbeidsongeschikt was; sindsdien werkt hij als planner. Drie jaar later verslechtert zijn rug door dezelfde aandoening en is hij 50% arbeidsongeschikt. Wat geldt?", [["Hij kan alsnog WIA krijgen: het gebeurt binnen vijf jaar en door dezelfde oorzaak", "Een 35-minner kan alsnog WIA krijgen als hij binnen vijf jaar na de wachttijd door dezelfde oorzaak ten minste 35% arbeidsongeschikt wordt."], ["Hij heeft nooit meer recht op WIA, omdat hij na de wachttijd al eens definitief is afgewezen", "Een eerdere afwijzing sluit later recht niet uit; de wet kent juist een regeling voor toename door dezelfde oorzaak."], ["Hij moet eerst opnieuw een wachttijd van 104 weken doorlopen", "Bij toename door dezelfde oorzaak binnen de termijn geldt geen nieuwe volledige wachttijd."], ["Hij kan alleen een IVA-uitkering krijgen", "Bij 50% arbeidsongeschiktheid komt de WGA in beeld, niet de IVA."]], "1d.5"],
["Wat kan een werknemer doen als hij het niet eens is met de WIA-beslissing van het UWV?", [["Binnen zes weken bezwaar maken bij het UWV", "Tegen een besluit van het UWV staat bezwaar open bij het UWV zelf; de termijn is zes weken."], ["Binnen twee weken een klacht indienen bij het Kifid", "Het Kifid behandelt geschillen met financiële dienstverleners, niet met het UWV."], ["Binnen zes maanden direct naar de Hoge Raad", "Eerst volgt bezwaar en daarna eventueel beroep bij de rechtbank."], ["Binnen een jaar een verzoek doen bij de Nationale ombudsman", "De ombudsman behandelt klachten over gedrag, niet de inhoud van een uitkeringsbesluit."]], "1k.5"],
["Speelt het inkomen of vermogen van de partner een rol bij de hoogte van een WIA-uitkering?", [["Nee, de WIA is een werknemersverzekering zonder partner- of vermogenstoets", "De WIA-uitkering hangt af van het eigen dagloon en de mate van arbeidsongeschiktheid, niet van het huishouden."], ["Ja, het vermogen van het huishouden boven een vrijstelling wordt in mindering gebracht", "Een vermogenstoets kent bijvoorbeeld de bijstand, niet de WIA."], ["Ja, het inkomen van de partner wordt volledig verrekend", "Verrekening met partnerinkomen hoort bij de Toeslagenwet en de bijstand, niet bij de WIA zelf."], ["Alleen in de vervolgfase wordt het partnerinkomen meegeteld", "Ook in de vervolgfase speelt het partnerinkomen voor de WIA geen rol."]], "1k.10"],
["Wat doet de Toeslagenwet?", [["Een uitkering aanvullen tot het sociaal minimum, rekening houdend met het partnerinkomen", "Een toeslag is mogelijk als de uitkering onder het sociaal minimum ligt; het inkomen van de partner wordt daarbij meegewogen."], ["Een werknemersuitkering aanvullen tot het niveau van het laatstverdiende loon van de werknemer", "De Toeslagenwet vult aan tot het sociaal minimum, niet tot het eerdere loon."], ["Huurtoeslag en zorgtoeslag verstrekken aan mensen met een uitkering", "Huur- en zorgtoeslag vallen onder de Awir en Dienst Toeslagen, niet onder de Toeslagenwet."], ["Alleen alleenstaanden met een lage uitkering een aanvulling geven", "Ook gehuwden en samenwonenden kunnen een toeslag krijgen, afhankelijk van het partnerinkomen."]], "1i.2"],
["Waar kan een jonggehandicapte met arbeidsvermogen sinds 2015 in de regel terecht voor ondersteuning?", [["Bij de gemeente, op grond van de Participatiewet", "Sinds 2015 komen jongeren met arbeidsvermogen niet meer in de Wajong; de gemeente ondersteunt hen via de Participatiewet."], ["Bij het UWV, dat hen een volledige Wajong-uitkering geeft", "De Wajong is sinds 2015 alleen nog voor wie duurzaam geen arbeidsvermogen heeft."], ["Bij de SVB, die hen een jeugduitkering betaalt", "De SVB voert volksverzekeringen uit en heeft geen rol bij jonggehandicapten met arbeidsvermogen."], ["Bij de zorgverzekeraar, via de Wet langdurige zorg", "De Wlz regelt zorg, geen inkomen of arbeidsondersteuning."]], "1i.2"],
["Wat is een uitgangspunt van de Wet vereenvoudiging Wajong?", [["Werken moet lonen: wie naast de Wajong meer verdient, gaat er in totaal op vooruit", "De vereenvoudiging zorgt ervoor dat Wajongers met werk altijd meer overhouden dan zonder werk."], ["De Wajong-uitkering stopt zodra iemand betaald werk aanvaardt", "Juist werken naast de Wajong blijft mogelijk; de uitkering wordt verrekend, niet beëindigd."], ["De Wajong wordt eenmalig als vast kapitaal uitgekeerd", "De Wajong is een periodieke uitkering en geen eenmalig kapitaal."], ["Het inkomen van de partner wordt voortaan met de Wajong-uitkering verrekend, net als in de bijstand", "De Wajong kent geen partnertoets; die wet heeft dat niet ingevoerd."]], "1i.2"],
["Daan (17) zit op het mbo en woont bij zijn ouders, die samen € 5.000 bruto per maand verdienen. Hij heeft nooit in loondienst gewerkt, ook niet als bijbaan. Bij een verkeersongeval raakt hij ernstig gewond. Het UWV stelt vast dat hij duurzaam geen arbeidsvermogen heeft. Welke regeling komt het eerst in beeld?", [["De Wajong, omdat hij voor zijn 18e arbeidsongeschikt is geworden", "Daan was geen verzekerde werknemer en kan daarom geen WIA krijgen; als jonggehandicapte kan hij wel de Wajong aanvragen."], ["De WIA, na afloop van een wachttijd van 104 weken", "De WIA is alleen voor werknemers die verzekerd waren; Daan heeft nooit gewerkt."], ["De Ziektewet, omdat hij geen werkgever heeft die loon betaalt", "De ZW is een werknemersverzekering voor wie eerder verzekerd was; Daan valt daar niet onder."], ["De Anw, omdat zijn ouders voor hem moeten zorgen", "De Anw is een nabestaandenregeling en heeft niets met arbeidsongeschiktheid te maken."]], "1i.2"],
["Hoe hoog is de WW-uitkering?", [["De eerste twee maanden 75% van het dagloon, daarna 70%", "De WW start op 75% van het (gemaximeerde) dagloon en daalt na twee maanden naar 70%."], ["Steeds 70% van het laatstverdiende brutoloon, zonder maximum", "Het dagloon is gemaximeerd en de eerste twee maanden geldt een hoger percentage."], ["Een vast bedrag op het niveau van het sociaal minimum", "De WW is loongerelateerd; een aanvulling tot het minimum loopt via de Toeslagenwet."], ["100% de eerste maand, daarna 70% van het dagloon", "Een volledige doorbetaling in de eerste maand kent de WW niet."]], "1i.2"],
["Wat is de maximale duur van een WW-uitkering?", [["24 maanden", "Sinds de verkorting van de WW is de maximale duur 24 maanden, bij een lang arbeidsverleden."], ["38 maanden", "38 maanden was de oude maximumduur; die is stapsgewijs teruggebracht."], ["12 maanden", "12 maanden is te kort; met een lang arbeidsverleden is de duur langer."], ["Onbeperkt, tot de AOW-leeftijd", "De WW is een tijdelijke uitkering met een maximumduur."]], "1i.2"],
["Lars (26) werkte na zijn studie anderhalf jaar als junior consultant voor € 3.200 bruto per maand. Hij woont samen met zijn vriendin. Zijn tijdelijke contract wordt niet verlengd en hij vraagt WW aan. Hij voldoet wel aan de wekeneis, maar niet aan de jareneis. Hoe lang krijgt hij WW?", [["Drie maanden", "Wie alleen aan de wekeneis voldoet, krijgt een korte WW-uitkering van drie maanden."], ["Geen WW, want beide eisen moeten zijn vervuld", "Voor het basisrecht volstaat de wekeneis; de jareneis bepaalt alleen of de duur langer wordt."], ["Zes maanden, ongeacht zijn arbeidsverleden", "Een vaste duur van zes maanden bestaat niet voor deze situatie."], ["Een maand per gewerkt jaar, met een minimum van een jaar", "Een duur per gewerkt jaar vereist dat ook aan de jareneis is voldaan."]], "1i.2"],
["Wat houdt de jareneis in de WW in?", [["In vier van de vijf voorgaande kalenderjaren telkens minimaal 208 uur loon", "Wie aan de jareneis voldoet, krijgt een WW-duur die afhangt van zijn arbeidsverleden, in plaats van alleen drie maanden."], ["In de laatste 36 weken ten minste 26 weken hebben gewerkt", "Dat is de wekeneis (referte-eis), niet de jareneis."], ["Ten minste vijf jaar onafgebroken bij dezelfde werkgever in dienst zijn geweest", "De jareneis vraagt geen dienstverband bij één werkgever."], ["In elk van de laatste vier kalenderjaren fulltime in loondienst hebben gewerkt", "Fulltime werken is geen eis; het gaat om een minimum aantal uren met loon per jaar."]], "1i.2"],
["Welke verplichting heeft iemand met een WW-uitkering in elk geval?", [["Actief naar werk zoeken en zijn sollicitaties aan het UWV doorgeven", "Een WW-gerechtigde moet zich inspannen om werk te vinden en kunnen aantonen dat hij solliciteert."], ["Gedurende de hele WW alleen werk op zijn eigen niveau aanvaarden", "Wat als passend werk geldt, wordt ruimer naarmate de WW langer duurt."], ["Elk jaar zijn vermogen aan het UWV opgeven", "De WW kent geen vermogenstoets; vermogen speelt geen rol."], ["Zorgen dat ook zijn partner ingeschreven staat als werkzoekende", "De verplichtingen gelden voor de uitkeringsgerechtigde zelf, niet voor zijn partner."]], "1k.5"],
["Wat gebeurt er met het begrip 'passende arbeid' naarmate de WW langer duurt?", [["Het wordt ruimer: ook lager betaald werk of werk op lager niveau is passend", "De WW-gerechtigde moet zijn zoekgebied geleidelijk verbreden; na verloop van tijd is vrijwel alle arbeid passend."], ["Het blijft gelijk: gedurende de hele WW is alleen werk op het eigen opleidingsniveau passend", "Het begrip verruimt juist in de loop van de tijd."], ["Het wordt enger: alleen werk bij de vorige werkgever is passend", "Er is geen beperking tot de vorige werkgever."], ["Het speelt geen rol meer na de eerste drie maanden", "Passende arbeid blijft gedurende de hele WW van belang."]], "1k.5"],
["Saskia (46) is HR-adviseur en verdient € 4.100 bruto per maand. Zij is getrouwd en heeft een zoon van tien. Na een conflict sluit zij op initiatief van haar werkgever een vaststellingsovereenkomst die haar dienstverband per direct beëindigt. Haar opzegtermijn zou twee maanden zijn geweest. Wat is het gevolg voor haar WW?", [["Haar WW gaat pas in na afloop van de fictieve opzegtermijn", "Wordt de opzegtermijn niet in acht genomen, dan schuift het UWV de ingangsdatum van de WW op met die termijn."], ["Zij krijgt geen WW, omdat zij zelf heeft ingestemd", "Met een vaststellingsovereenkomst kan WW-recht bestaan; instemming maakt haar niet verwijtbaar werkloos."], ["Haar WW gaat direct in en wordt met twee maanden verlengd", "De opzegtermijn verlengt de WW niet; de ingangsdatum schuift op."], ["De werkgever moet haar WW over twee maanden aan het UWV terugbetalen", "Het UWV verhaalt niets op de werkgever; de werknemer krijgt later WW."]], "1i.2"],
["Onder welke voorwaarde kan een werknemer na een beëindiging met een vaststellingsovereenkomst WW krijgen?", [["Het initiatief ligt bij de werkgever en er is geen dringende reden voor ontslag", "Een vaststellingsovereenkomst sluit WW niet uit, mits de werknemer niet verwijtbaar werkloos is: het initiatief komt van de werkgever en er is geen dringende reden."], ["De werknemer heeft zelf om beëindiging van het dienstverband gevraagd, om elders te beginnen", "Wie zelf zonder dringende reden om ontslag vraagt, is verwijtbaar werkloos."], ["De overeenkomst is vooraf door de kantonrechter goedgekeurd", "Een vaststellingsovereenkomst hoeft niet door de rechter te worden goedgekeurd."], ["De werknemer ziet af van zijn recht op een transitievergoeding", "Afzien van de transitievergoeding is geen voorwaarde voor WW."]], "1i.2"],
["Wendy (51) werkte twintig jaar als administrateur bij een drukkerij en verdiende € 3.300 bruto per maand. Zij is getrouwd en haar kinderen wonen op zichzelf. Om bedrijfseconomische redenen wordt zij ontslagen en zij ontvangt een transitievergoeding. Daarna vraagt zij WW aan. Wat is de invloed van de vergoeding op haar WW?", [["Geen; de transitievergoeding wordt niet met de WW verrekend", "De transitievergoeding is een compensatie voor ontslag en wordt niet in mindering gebracht op de WW."], ["De WW wordt verlaagd met het volledige bedrag van de vergoeding", "Er is geen verrekening; de WW wordt niet verlaagd."], ["De WW gaat pas in als de vergoeding is opgemaakt", "Die regel bestaat niet; de WW start los van de transitievergoeding."], ["De WW-duur wordt korter naarmate de vergoeding hoger is", "De duur hangt af van het arbeidsverleden, niet van de hoogte van de vergoeding."]], "1i.2"],
["Bas (37) is zzp'er als webdeveloper en maakte vorig jaar € 55.000 winst. Hij is getrouwd en heeft twee jonge kinderen. Zijn belangrijkste opdrachtgever beëindigt de samenwerking en Bas heeft maandenlang nauwelijks omzet. Hij is niet ziek, maar zijn inkomen valt grotendeels weg. Waarop kan hij een beroep doen?", [["Niet op de WW; wel eventueel op de bijstand voor zelfstandigen (Bbz) via de gemeente", "Een zelfstandige is niet verzekerd voor de WW; de gemeente kan onder voorwaarden ondersteuning bieden."], ["Op een WW-uitkering die wordt berekend op basis van zijn gemiddelde winst van de afgelopen jaren", "De WW geldt alleen voor werknemers; winst uit onderneming geeft geen WW-recht."], ["Op een ZW-uitkering, omdat hij geen werkgever heeft", "De ZW is voor zieke werknemers zonder werkgever, niet voor ondernemers zonder opdrachten."], ["Op zijn AOV, omdat die ook omzetverlies dekt", "Een AOV dekt inkomensverlies door arbeidsongeschiktheid, niet door gebrek aan opdrachten."]], "1i.7"],
["Wat is een kenmerk van de IOW ten opzichte van de bijstand?", [["Het vermogen en het inkomen van de partner tellen niet mee", "De IOW is een vervolguitkering voor oudere werklozen zonder vermogens- en partnertoets, anders dan de bijstand."], ["Het eigen vermogen wordt volledig getoetst", "Een vermogenstoets kent de bijstand juist wel en de IOW niet."], ["De uitkering wordt verstrekt door de gemeente", "De IOW wordt uitgevoerd door het UWV."], ["De uitkering is altijd een lening die terugbetaald moet worden", "De IOW is een gewone uitkering en geen lening."]], "1i.2"],
["Maarten (58) was inkoper bij een winkelketen en verdiende € 3.700 bruto per maand. Hij is alleenstaand en woont in een koopwoning met een flinke overwaarde. Na zijn ontslag vond hij geen nieuwe baan en inmiddels is zijn WW afgelopen. Hij vraagt bijstand aan. Waarmee moet hij rekening houden?", [["Door het vermogen in zijn woning kan de bijstand worden verstrekt als geldlening", "De bijstand kent een vermogenstoets; bij vermogen in de eigen woning boven de grens kan de gemeente bijstand als lening verstrekken."], ["Hij moet de woning eerst verkopen en de overwaarde opmaken voordat hij bijstand kan krijgen", "Verkoop is niet vereist; de gemeente kan bijstand in de vorm van een lening geven."], ["De overwaarde speelt geen rol, alleen het spaargeld telt", "Ook vermogen in de eigen woning wordt bij de vermogenstoets betrokken."], ["Hij krijgt een IOW-uitkering, omdat hij een eigen woning heeft", "Het bezit van een woning geeft geen recht op IOW; die hangt af van leeftijd en de WW-situatie."]], "1i.2"],
["Wouter (43) was verkoper bij een autobedrijf en verdiende € 3.400 bruto per maand. Hij is getrouwd en heeft drie kinderen. Sinds januari ontvangt hij WW en dit jaar heeft hij niet gewerkt. Hij vraagt of hij over zijn WW-uitkering arbeidskorting krijgt. Wat is juist?", [["Nee, arbeidskorting geldt alleen over inkomen uit arbeid", "Arbeidskorting is een heffingskorting voor werkenden; een uitkering telt daarvoor niet mee."], ["Ja, de WW wordt voor de arbeidskorting gelijkgesteld aan loon", "De WW is geen arbeidsinkomen voor de arbeidskorting."], ["Ja, maar alleen in de eerste twee maanden van de WW", "Er is geen tijdelijke arbeidskorting over WW."], ["Alleen als hij daarnaast een parttimebaan heeft, over het totaal", "Ook dan geldt de arbeidskorting alleen over het arbeidsinkomen en niet over de WW."]], "1i.5"],
["Hoe is de positie van een zelfstandige zonder personeel (zzp'er), die voor de inkomstenbelasting als ondernemer geldt, binnen de sociale zekerheid?", [["Hij is niet verzekerd voor de werknemersverzekeringen, wel voor de volksverzekeringen", "Een zzp'er valt buiten ZW, WIA en WW, maar is als inwoner van Nederland wel verzekerd voor volksverzekeringen zoals AOW en Anw."], ["Hij is net als een werknemer verplicht verzekerd voor ZW, WIA en WW", "Werknemersverzekeringen gelden voor wie in dienstbetrekking werkt, niet voor een ondernemer."], ["Hij is voor geen enkele sociale verzekering verzekerd", "Voor de volksverzekeringen, zoals de AOW, is een zzp'er die in Nederland woont wel verzekerd."], ["Hij is alleen verzekerd voor de WW, omdat hij opdrachten kan verliezen", "Een zzp'er is niet verzekerd voor de WW; bij wegvallen van opdrachten is er geen WW-uitkering."]], "1a.8"],
["Welke voorwaarde moet in elk geval voor de overledene gelden voor een Anw-uitkering aan de nabestaande?", [["De overledene was Anw-verzekerd, bijvoorbeeld door in Nederland te wonen of werken", "De Anw is een volksverzekering: de overledene moet op het moment van overlijden verzekerd zijn geweest."], ["De overledene had ten minste tien jaar Anw-premie betaald via zijn loon", "Er geldt geen minimale premieperiode; verzekerd zijn op het moment van overlijden is bepalend."], ["De overledene had een aanvullende Anw-hiaatverzekering", "Een hiaatverzekering is particulier en geen voorwaarde voor de wettelijke Anw."], ["De overledene was op het moment van overlijden in loondienst bij een in Nederland gevestigde werkgever", "Ook wie niet in loondienst was, bijvoorbeeld een zelfstandige, kan verzekerd zijn als ingezetene."]], "1i.2"],
["Casus: Tim en Rosa wonen ongehuwd samen en voeren een gezamenlijke huishouding. Zij hebben een zoon van vijf. Tim overlijdt. Kan Rosa een Anw-uitkering krijgen?", [["Ja, ongehuwd samenwonenden met een gezamenlijke huishouding gelden ook als partner", "De Anw kijkt naar de gezamenlijke huishouding; met een kind onder de 18 kan Rosa recht hebben, met inachtneming van de inkomenstoets."], ["Nee, alleen gehuwden en geregistreerd partners hebben recht op een Anw-nabestaandenuitkering", "Ook ongehuwd samenwonenden kunnen onder de Anw als partner gelden."], ["Nee, omdat zij geen samenlevingscontract hebben", "Een samenlevingscontract is niet vereist; het gaat om de feitelijke gezamenlijke huishouding."], ["Alleen hun zoon heeft recht, op een wezenuitkering", "Een wezenuitkering is voor kinderen van wie beide ouders zijn overleden; Rosa leeft nog."]], "1i.2"],
["Welk soort inkomen of vermogen speelt GEEN rol bij de hoogte van een Anw-nabestaandenuitkering?", [["Het vermogen van de nabestaande, zoals spaargeld", "De Anw kent een inkomenstoets, maar geen vermogenstoets: spaargeld heeft geen invloed."], ["Het loon uit een baan van de nabestaande", "Inkomen uit arbeid wordt gedeeltelijk met de Anw verrekend."], ["Een WIA-uitkering van de nabestaande", "Uitkeringen in verband met arbeid, zoals de WIA, worden met de Anw verrekend."], ["De winst uit onderneming die de nabestaande zelf maakt", "Ook winst is inkomen uit arbeid dat met de Anw wordt verrekend."]], "1i.2"],
["Petra (47) is parttime receptioniste en verdient € 1.400 bruto per maand. Haar man overleed vijf jaar geleden en sindsdien ontvangt zij een Anw-uitkering, omdat zij voor hun dochter zorgt. Haar dochter wordt binnenkort 18 jaar. Petra is niet arbeidsongeschikt. Wat gebeurt er?", [["De Anw-uitkering stopt", "Het recht op Anw is gekoppeld aan de zorg voor een kind jonger dan 18; zonder andere grond eindigt de uitkering."], ["De uitkering loopt door tot Petra de AOW-leeftijd bereikt", "Doorlopen tot de AOW-leeftijd is alleen mogelijk als zij aan een andere voorwaarde voldoet, zoals arbeidsongeschiktheid."], ["De uitkering loopt door zolang de dochter studeert", "Studie van het kind verlengt de nabestaandenuitkering niet."], ["De uitkering wordt omgezet in een wezenuitkering voor de dochter", "Een wezenuitkering geldt alleen als beide ouders zijn overleden."]], "1i.2"],
["Casus: Gerard (52) verliest zijn vrouw. Zij hebben geen kinderen. Gerard is voor 50% arbeidsongeschikt. Kan hij een Anw-uitkering krijgen?", [["Ja, bij ten minste 45% arbeidsongeschiktheid, afhankelijk van zijn inkomen", "Naast de zorg voor een kind onder de 18 geeft ook arbeidsongeschiktheid van ten minste 45% toegang tot de Anw."], ["Nee, zonder kinderen jonger dan 18 jaar bestaat voor een weduwnaar nooit recht op Anw", "Arbeidsongeschiktheid is een zelfstandige grond voor de Anw."], ["Nee, de Anw is alleen bedoeld voor weduwen", "De Anw maakt geen onderscheid tussen mannen en vrouwen."], ["Ja, maar pas als hij 60 jaar is", "Een leeftijdsgrens van 60 jaar bestaat niet in de Anw."]], "1i.2"],
["Hoe wordt een Anw-uitkering fiscaal behandeld?", [["Als belast inkomen in box 1; de SVB houdt loonheffing in", "De Anw is een publieke uitkering die als inkomen wordt belast."], ["Als onbelaste uitkering, net als een ORV-uitkering", "Een ORV-kapitaal valt niet in box 1, maar de Anw is wel belast."], ["Als vermogen in box 3 op de peildatum", "Een periodieke Anw-uitkering is inkomen, geen box 3-vermogen."], ["Onder de erfbelasting, omdat de uitkering door overlijden ontstaat", "De Anw is een sociale uitkering en valt niet onder de erfbelasting."]], "1i.5"],
["Waarom is het verstandig de eindleeftijd van een AOV af te stemmen op de AOW-leeftijd?", [["Omdat de AOW pas dan ingaat en het inkomensgat tot dat moment gedekt moet zijn", "Stopt de AOV eerder, dan ontstaat tussen eindleeftijd en AOW-leeftijd een periode zonder inkomen bij arbeidsongeschiktheid."], ["Omdat de premie dan fiscaal pas aftrekbaar wordt", "Aftrekbaarheid van de premie hangt niet af van de eindleeftijd."], ["Omdat een AOV wettelijk altijd tot de AOW-leeftijd moet lopen", "Er is geen wettelijke verplichting; een lagere eindleeftijd is mogelijk, maar riskant."], ["Omdat de verzekeraar anders geen wachttijd mag hanteren", "De wachttijd staat los van de eindleeftijd."]], "1g.8"],
["Wat houdt indexatie van een AOV-uitkering in?", [["De uitkering stijgt tijdens arbeidsongeschiktheid met een vast percentage of met de inflatie", "Indexatie beschermt tegen koopkrachtverlies bij langdurige arbeidsongeschiktheid."], ["Het verzekerd bedrag wordt elk jaar automatisch verlaagd naarmate de verzekerde ouder wordt en het risico stijgt", "Dat is geen indexatie maar een daling; indexatie verhoogt juist."], ["De premie wordt jaarlijks aangepast aan het schadeverloop van de verzekeraar", "Dat betreft een premieaanpassing, niet de indexatie van de uitkering."], ["De wachttijd wordt automatisch korter als de verzekerde langer verzekerd is", "Indexatie heeft niets met de wachttijd te maken."]], "1g.5"],
["Merel (31) is zzp'er als communicatieadviseur en maakt € 50.000 winst per jaar. Zij woont samen en heeft een zoon van één. Om premie te besparen kiest zij een AOV met een uitkeringsduur van maximaal vijf jaar per claim. Haar adviseur wil haar wijzen op het risico daarvan. Wat is het belangrijkste nadeel?", [["Bij langdurige AO stopt de uitkering, terwijl haar inkomensverlies doorloopt", "Een beperkte uitkeringsduur verlaagt de premie, maar laat het risico van blijvende arbeidsongeschiktheid grotendeels onverzekerd."], ["De premie is hoger dan bij een vergelijkbare uitkering die doorloopt tot de eindleeftijd", "Een kortere uitkeringsduur leidt juist tot een lagere premie."], ["De uitkering is fiscaal niet belast, maar de premie ook niet aftrekbaar", "De uitkeringsduur verandert niets aan de fiscale behandeling."], ["Zij krijgt geen uitkering bij gedeeltelijke arbeidsongeschiktheid", "Of gedeeltelijke arbeidsongeschiktheid gedekt is, hangt af van de drempel, niet van de uitkeringsduur."]], "1g.8"],
["Wat betekent het criterium 'passende arbeid' in een AOV?", [["Hij is arbeidsongeschikt als hij geen werk kan doen dat past bij opleiding en ervaring", "Passende arbeid ligt qua ruimte tussen beroepsarbeidsongeschiktheid en gangbare arbeid in."], ["Hij is alleen arbeidsongeschikt als hij geen enkele gangbare functie op de arbeidsmarkt meer kan doen", "Dat lijkt op het criterium gangbare arbeid, het smalste criterium."], ["Hij is arbeidsongeschikt als hij zijn eigen beroep niet meer kan uitoefenen", "Dat is beroepsarbeidsongeschiktheid, het ruimste criterium."], ["De verzekerde bepaalt zelf welk werk voor hem passend is", "Het oordeel ligt bij de verzekeraar op basis van objectieve maatstaven, niet bij de verzekerde."]], "1g.16"],
["Wat houdt de mededelingsplicht in bij het sluiten van een AOV?", [["De klant moet vooraf feiten melden die hij kent of behoort te kennen en die relevant zijn", "Deze precontractuele plicht volgt uit het Burgerlijk Wetboek en geldt voor alle feiten die de beoordeling van het risico kunnen beïnvloeden."], ["De verzekeraar moet de klant vooraf alle polisvoorwaarden uitgebreid uitleggen", "Informatieplichten van de verzekeraar bestaan wel, maar de mededelingsplicht rust op de verzekeringnemer."], ["De verzekerde moet tijdens de looptijd elke ziekmelding binnen 24 uur bij de verzekeraar doorgeven", "Dat is een plicht bij schade tijdens de looptijd, niet de mededelingsplicht vóór het sluiten."], ["De adviseur moet de medische gegevens van de klant doorgeven", "De klant geeft zijn gezondheidsgegevens zelf, rechtstreeks aan de medisch adviseur."]], "1a.2"],
["Hugo (44) is zelfstandig stukadoor en maakt € 48.000 winst per jaar. Hij is getrouwd en heeft twee kinderen. Bij het aanvragen van zijn AOV heeft hij op de gezondheidsverklaring bewust zijn jarenlange rugklachten en fysiotherapie verzwegen om een uitsluiting te voorkomen. Na drie jaar meldt hij zich arbeidsongeschikt door zijn rug. Wat kan de verzekeraar doen?", [["Een uitkering weigeren en de verzekering opzeggen, omdat Hugo opzettelijk heeft verzwegen", "Bij opzet tot misleiding vervalt het recht op uitkering en kan de verzekeraar de overeenkomst beëindigen."], ["Niets, want na twee jaar kan de verzekeraar zich niet meer op verzwijging beroepen", "Er geldt geen vervaltermijn van twee jaar die opzettelijke verzwijging dekt."], ["Alleen de premie met terugwerkende kracht verhogen en volledig uitkeren", "Bij opzet hoeft de verzekeraar niet uit te keren; een premiecorrectie speelt bij niet-opzettelijke verzwijging."], ["Hugo doorverwijzen naar het UWV voor een WIA-uitkering", "Een zelfstandige is niet verzekerd voor de WIA, dus die uitweg bestaat niet."]], "1a.2"],
["Karin (39) is zelfstandig fysiotherapeut en maakt € 58.000 winst per jaar. Zij is getrouwd en heeft een dochter van zes. Haar AOV heeft een drempel van 25% en keert uit naar rato van de mate van arbeidsongeschiktheid. Na een ernstige nekhernia stelt de verzekeraar vast dat zij 60% arbeidsongeschikt is. Wat ontvangt zij in principe?", [["Een uitkering die past bij 60% arbeidsongeschiktheid, niet het volledige bedrag", "Bij uitkering naar rato krijgt de verzekerde een deel van het verzekerde bedrag dat overeenkomt met de mate van arbeidsongeschiktheid."], ["Het volledige verzekerde bedrag, omdat zij ruim boven de polisdrempel van 25% uitkomt", "Boven de drempel uitkeren betekent niet automatisch een volledige uitkering."], ["Niets, omdat zij niet volledig arbeidsongeschikt is", "De drempel van 25% is gehaald, dus zij heeft recht op een uitkering."], ["Een uitkering van 25% van het verzekerde bedrag", "De drempel bepaalt wanneer er wordt uitgekeerd, niet hoeveel."]], "1g.3"],
["Wat is de ZEZ-uitkering (Zelfstandig en Zwanger)?", [["Een UWV-uitkering voor zelfstandigen rond zwangerschap en bevalling", "Ook zelfstandigen kunnen via het UWV een uitkering krijgen tijdens het zwangerschaps- en bevallingsverlof."], ["Een AOV-dekking die verzekeraars verplicht moeten aanbieden", "De ZEZ is een publieke regeling en geen verplichte AOV-dekking."], ["Een gemeentelijke lening voor zwangere ondernemers", "De ZEZ is geen lening en wordt niet door de gemeente verstrekt."], ["Een vrijstelling van inkomstenbelasting tijdens het verlof", "De ZEZ is een uitkering en geen fiscale vrijstelling; de uitkering is belast."]], "1i.6"],
["Esther (35) werkte tien jaar als laborant in loondienst voor € 3.300 bruto per maand. Zij is alleenstaand en gaat volgende maand verder als zelfstandig trainer. Door een migraineverleden verwacht zij dat een particuliere AOV lastig of duur wordt. Zij vraagt welke alternatieven er zijn. Welke mogelijkheid kan een adviseur naast een particuliere AOV met haar bespreken?", [["Onder voorwaarden en binnen een beperkte termijn een vrijwillige verzekering bij het UWV", "Wie de verplichte werknemersverzekering verliest, kan zich onder voorwaarden vrijwillig verzekeren bij het UWV, bijvoorbeeld voor de WIA."], ["Haar recht op WIA behouden zonder verdere actie, omdat zij al tien jaar als werknemer premie betaalde", "Het verplichte verzekerd zijn eindigt bij het einde van de dienstbetrekking; opgebouwde jaren geven geen blijvende dekking."], ["Een WW-uitkering aanvragen als aanvulling in haar startjaar", "Wie vrijwillig stopt als werknemer om voor zichzelf te beginnen, is niet werkloos in de zin van de WW."], ["Een Wajong-uitkering, omdat zij een nieuw beroep begint", "De Wajong geldt voor wie op jonge leeftijd arbeidsongeschikt is geworden."]], "1i.4"],
["Wat houdt premievrijstelling bij arbeidsongeschiktheid in een AOV in?", [["Tijdens arbeidsongeschiktheid hoeft de verzekerde (naar rato) geen premie te betalen", "Premievrijstelling voorkomt dat de verzekerde premie moet blijven betalen terwijl hij door arbeidsongeschiktheid inkomen mist."], ["De premie wordt na de wachttijd volledig terugbetaald", "Er vindt geen terugbetaling plaats; de premie vervalt tijdens de arbeidsongeschiktheid."], ["De premie is fiscaal vrijgesteld en dus niet aftrekbaar", "Premievrijstelling is een polisvoorwaarde, geen fiscale regel."], ["De verzekerde hoeft het eerste jaar na ingang geen premie te betalen", "Een premievrij startjaar heeft niets te maken met premievrijstelling bij arbeidsongeschiktheid."]], "1g.9"],
["Wat is het belangrijkste verschil tussen een ongevallenverzekering en een AOV?", [["Een ongevallenverzekering keert alleen uit bij een ongeval, niet bij ziekte", "Een ongevallenverzekering geeft een uitkering bij blijvende invaliditeit of overlijden door een ongeval; ziekte, de meest voorkomende oorzaak van AO, valt erbuiten."], ["Een ongevallenverzekering dekt ook inkomensverlies door ziekte", "Ziekte valt juist buiten een ongevallenverzekering."], ["Een AOV keert alleen uit bij een bedrijfsongeval", "Een AOV dekt arbeidsongeschiktheid door ziekte en ongeval."], ["Een ongevallenverzekering geeft na een ongeval levenslang een maandelijks inkomen", "Een ongevallenverzekering keert meestal een eenmalig bedrag uit."]], "1f.1"],
["Welk risico dekt een WIA-35-minverzekering (ook wel WIA-bodemverzekering)?", [["Het inkomensverlies van een werknemer die minder dan 35% arbeidsongeschikt is verklaard", "Een 35-minner krijgt geen WIA; deze verzekering vult het inkomensverlies aan dat daardoor onverzekerd blijft."], ["Het loon boven het maximumdagloon bij volledige arbeidsongeschiktheid", "Dat is het domein van de WIA-excedentverzekering."], ["Het gat in de WGA-vervolgfase bij onvoldoende benutting van de resterende verdiencapaciteit", "Dat gat dekt de WGA-hiaatverzekering."], ["De loondoorbetaling door de werkgever in de eerste twee ziektejaren", "Dat risico van de werkgever dekt een verzuimverzekering."]], "1g.13"],
["Hoe wordt een premie voor een collectieve WGA-hiaatverzekering die de werkgever op het brutoloon van de werknemer inhoudt, fiscaal behandeld?", [["De premie verlaagt het belastbare loon; de latere uitkering is belast", "Voor deze inkomensverzekering geldt de omkeerregel: aftrek of inhouding vooraf en belasting over de uitkering."], ["De premie is niet aftrekbaar en de uitkering is onbelast", "Die behandeling hoort bij bijvoorbeeld een woonlastenverzekering, niet bij een WGA-hiaatverzekering."], ["De premie is aftrekbaar en de uitkering is ook onbelast", "Aftrek van de premie en een onbelaste uitkering gaan fiscaal niet samen; er geldt de omkeerregel."], ["De premie valt in box 3 en de uitkering onder de erfbelasting", "Box 3 en erfbelasting spelen bij deze arbeidsongeschiktheidsdekking geen rol."]], "1i.10"],
["Wanneer keert een WIA-excedentverzekering in de regel uit?", [["Als hij recht heeft op WIA en verdiende boven het maximumdagloon", "De excedentverzekering bouwt voort op de WIA-beoordeling en dekt het deel van het loon boven het maximumdagloon."], ["Al vanaf de eerste ziektedag, naast de loondoorbetaling door de werkgever", "In de eerste twee jaar betaalt de werkgever het loon door; de excedentdekking volgt op de WIA."], ["Alleen als de werknemer in de IVA terechtkomt", "Ook bij een WGA-uitkering kan de excedentverzekering uitkeren."], ["Ook als de werknemer minder dan 35% arbeidsongeschikt is", "Voor 35-minners bestaat een aparte dekking; de excedentverzekering volgt doorgaans de WIA."]], "1g.13"],
["Wie heeft het belang bij een verzekering van het WGA-eigenrisicodragerschap?", [["De werkgever, die als eigenrisicodrager de WGA-lasten van (ex-)werknemers draagt", "Een eigenrisicodrager betaalt zelf de WGA-uitkeringen; met deze verzekering dekt hij dat financiële risico af."], ["De werknemer, die daarmee het gat in de vervolgfase dekt", "Het gat voor de werknemer dekt de WGA-hiaatverzekering, niet de ERD-verzekering."], ["Het UWV, dat daarmee zijn eigen uitkeringslasten voor de WGA bij grote werkgevers beperkt", "Bij eigenrisicodragerschap betaalt de werkgever, niet het UWV; het UWV is geen verzekeringnemer."], ["De verzuimverzekeraar, die zo zijn eigen risico herverzekert", "Herverzekering van een verzekeraar is iets anders dan een ERD-verzekering voor de werkgever."]], "1i.13"],
["Rachid (38) is werkvoorbereider bij een aannemer en verdient € 3.800 bruto per maand. Hij is getrouwd en heeft twee kinderen. Via zijn werkgever is hij verzekerd met een collectieve WGA-hiaatverzekering. Hij krijgt een baan aangeboden bij een kleinere werkgever. Wat is het belangrijkste aandachtspunt?", [["Nagaan of de nieuwe werkgever een vergelijkbare dekking biedt", "Een collectieve verzekering geldt voor werknemers van die werkgever; bij vertrek kan een dekkingsgat ontstaan."], ["Niets, want de collectieve dekking gaat automatisch mee naar de volgende werkgever", "Een collectieve polis hoort bij de werkgever; die dekking gaat niet vanzelf mee."], ["De dekking omzetten naar een woonlastenverzekering", "Een woonlastenverzekering is tijdelijk en dekt alleen woonlasten; dat is geen gelijkwaardige vervanging."], ["Een WW-uitkering aanvragen voor de periode zonder dekking", "Een dekkingsgat bij baanwissel geeft geen recht op WW."]], "1j.3"],
["Wat is in een verzuimverzekering de eigenrisicoperiode?", [["De eerste periode van verzuim waarin de werkgever het loon zelf draagt", "Een eigenrisicoperiode, uitgedrukt in dagen of weken, verlaagt de premie maar laat kort verzuim voor rekening van de werkgever."], ["De periode na de ziekmelding waarin de werknemer geen loon krijgt", "Dat gaat over wachtdagen voor de werknemer, niet over het eigen risico van de werkgever onder de polis."], ["De periode waarin de verzekeraar alleen de re-integratiekosten van de werkgever vergoedt", "In de eigenrisicoperiode vergoedt de verzekeraar juist geen loon."], ["De periode na twee jaar ziekte waarin de WIA ingaat", "Na twee jaar eindigt de loondoorbetaling; dat staat los van het eigen risico in de verzuimpolis."]], "1g.10"],
["Waarom kiezen werkgevers bij een verzuimverzekering vaak voor een opslag op het verzekerde loon?", [["Om ook werkgeverslasten zoals sociale premies, pensioenpremie en vakantiegeld te dekken", "Bij ziekte lopen naast het brutoloon ook andere loonkosten door; met een opslag verzekert de werkgever die mee."], ["Om ook de loonsanctie van het UWV bij onvoldoende re-integratie mee te verzekeren", "Een opslag dekt loonkosten bij gewoon verzuim; een loonsanctie is meestal uitgesloten."], ["Om de werknemer meer dan zijn eigen loon te laten ontvangen", "De uitkering gaat naar de werkgever; de werknemer krijgt het loon waarop hij recht heeft."], ["Omdat de wet een minimale opslag op de verzekerde som voorschrijft", "Een verzuimverzekering is vrijwillig en kent geen wettelijke opslag."]], "1g.10"],
["Wordt een loonsanctie van het UWV doorgaans gedekt door een verzuimverzekering?", [["Nee, een loonsanctie door onvoldoende re-integratie is in de regel uitgesloten", "Een loonsanctie is een gevolg van eigen tekortkomingen van de werkgever; verzekeraars dekken dat in de regel niet."], ["Ja, alle loonkosten van zieke werknemers zijn volledig gedekt", "Een loonsanctie is geen gewoon verzuimrisico maar een sanctie; die valt doorgaans buiten de dekking."], ["Ja, maar alleen als de werkgever ook eigenrisicodrager voor de WGA en de ZW is", "Eigenrisicodragerschap heeft geen invloed op de dekking van een loonsanctie."], ["Alleen als de werknemer zelf de sanctie veroorzaakte", "De loonsanctie treft de werkgever, wegens diens tekortkomingen in de re-integratie."]], "1g.4"],
["Hoe worden de premie en de uitkering van een verzuimverzekering bij een ondernemer fiscaal behandeld?", [["De premie is een aftrekbare bedrijfslast en de uitkering is belaste bedrijfsopbrengst", "De verzuimverzekering dekt een bedrijfsrisico; premie en uitkering lopen daarom via het fiscale resultaat van de onderneming."], ["De premie is niet aftrekbaar en de uitkering is onbelast", "Dat is de behandeling van bijvoorbeeld een woonlastenverzekering voor een particulier."], ["De premie is aftrekbaar in box 1 als uitgave voor inkomensvoorziening van de ondernemer", "Die aftrek geldt voor een eigen AOV, niet voor verzuim van werknemers."], ["De uitkering wordt als loon van de zieke werknemer belast", "De uitkering gaat naar de werkgever; het loon van de werknemer wordt apart belast."]], "1i.5"],
["Waarom stellen verzuimverzekeraars vaak eisen aan de verzuimbegeleiding door de werkgever?", [["Goede begeleiding beperkt de schadelast; zonder naleving kan de uitkering worden beperkt", "Verzekeraars verbinden aan de dekking voorwaarden over arbodienst en Poortwachter, omdat snelle re-integratie het verzuim verkort."], ["Omdat de AFM dat voorschrijft als voorwaarde voor de vergunning van de verzekeraar", "Deze eisen volgen uit de polisvoorwaarden van de verzekeraar, niet uit een AFM-voorschrift."], ["Omdat de verzekeraar daarmee de rol van het UWV overneemt", "Het UWV blijft verantwoordelijk voor de WIA-beoordeling; de verzekeraar neemt dat niet over."], ["Omdat de werknemer anders geen recht heeft op loondoorbetaling", "Het recht op loondoorbetaling volgt uit de wet en staat los van de verzuimverzekering."]], "1d.3"],
["Zelfstandige Koen heeft een AOV die als sommenverzekering een vast bedrag per maand uitkeert. Hij raakt arbeidsongeschikt door een verkeersongeval waarvoor een ander aansprakelijk is. Kan de verzekeraar de AOV-uitkering verhalen op de aansprakelijke partij?", [["Nee, bij een sommenverzekering gaat het verhaalsrecht niet over op de verzekeraar", "Subrogatie geldt alleen bij een schadeverzekering. Bij een sommenverzekering kan Koen zijn eigen schade zelf op de aansprakelijke partij verhalen."], ["Ja, de verzekeraar treedt altijd in de rechten van de verzekerde", "Dat geldt bij een schadeverzekering, niet bij een sommenverzekering."], ["Ja, maar pas nadat de aansprakelijke partij zelf aan Koen heeft betaald", "De verzekeraar keert uit op grond van de polis, los van een eventuele aansprakelijkheid van een derde."], ["Nee, omdat een AOV nooit een persoonsverzekering kan zijn", "Een AOV als sommenverzekering is juist een persoonsverzekering."]], "1f.3"],
["Een werkgever wil eigenrisicodrager worden voor de WGA. Wat geldt voor de procedure?", [["Hij vraagt dit ten minste 13 weken vooraf aan bij de Belastingdienst, met een garantieverklaring", "Eigenrisicodragerschap gaat in per 1 januari of 1 juli. De aanvraag gaat met een garantieverklaring van een verzekeraar of bank naar de Belastingdienst."], ["Hij kan op elk moment van het jaar met directe ingang overstappen via het UWV", "Overstappen kan alleen per vaste data en de aanvraag moet tijdig worden gedaan."], ["Hij heeft daarvoor toestemming nodig van de AFM", "De AFM speelt geen rol bij het eigenrisicodragerschap; een garantieverklaring is wel nodig."], ["Hij moet minimaal honderd werknemers hebben en een eigen bedrijfsarts in dienst", "Er geldt geen minimumaantal werknemers voor eigenrisicodragerschap voor de WGA."]], "1f.9"],
["Wat is het doel van de private aanvulling op de WW en de loongerelateerde WGA (PAWW) die in veel cao's is afgesproken?", [["De verkorting van de maximale duur van WW en loongerelateerde WGA repareren", "Via de cao kan een werknemer na afloop van de wettelijke WW of loongerelateerde WGA een aanvullende uitkering krijgen, tot de duur die vóór de verkorting gold."], ["Het loon boven het maximumdagloon aanvullen tijdens de WW", "Dat is het doel van een private WW-aanvullingsverzekering; de PAWW repareert de duur, niet de hoogte boven het maximumdagloon."], ["Zzp'ers alsnog een WW-uitkering geven bij gebrek aan opdrachten", "De PAWW geldt voor werknemers onder een deelnemende cao, niet voor zelfstandigen."], ["De WW-uitkering verhogen tot 100% van het laatstverdiende loon", "De PAWW verlengt de uitkeringsduur en verhoogt het uitkeringspercentage niet."]], "1g.17"],
["Een werkgever beëindigt zijn verzuimverzekering en stapt over naar een andere verzekeraar. Een werknemer is op dat moment al vier maanden ziek. Wat is het belangrijkste aandachtspunt?", [["Of het lopende ziektegeval via uitloop bij de oude of via inloop bij de nieuwe verzekeraar gedekt is", "Zonder afspraken over uitloop of inloop kan de werkgever het loon van de zieke werknemer zelf moeten dragen."], ["Niets, de nieuwe verzekeraar neemt lopende ziektegevallen altijd automatisch over", "Een nieuwe verzekeraar sluit lopend verzuim vaak uit, tenzij inloop uitdrukkelijk is meeverzekerd."], ["De werknemer moet zich opnieuw ziek melden bij het UWV", "Een wisseling van verzuimverzekeraar heeft geen gevolgen voor de ziekmelding bij het UWV."], ["De loondoorbetalingsplicht van de werkgever vervalt bij de overstap", "De loondoorbetalingsplicht staat los van de verzekering en blijft gewoon bestaan."]], "1g.19"],
["Welke combinatie van factoren bepaalt vooral de hoogte van de premie van een particuliere AOV?", [["Beroep, leeftijd, verzekerd bedrag, wachttijd en eindleeftijd", "Het beroepsrisico, de leeftijd en de gekozen dekking bepalen samen hoe groot het risico voor de verzekeraar is, en daarmee de premie."], ["Woonplaats, burgerlijke staat en het aantal kinderen", "Deze persoonlijke omstandigheden zijn geen belangrijke premiefactoren voor een AOV."], ["Alleen het inkomen en de rechtsvorm van de onderneming", "Het inkomen speelt mee via het verzekerd bedrag, maar beroep, leeftijd en dekkingskeuzes zijn bepalend."], ["Het vermogen van de verzekerde en de waarde van zijn woning", "Vermogen en woningwaarde zijn geen gangbare premiefactoren voor een AOV."]], "1h.4"],
["Waarom geldt bij de werkloosheidsdekking van een woonlastenverzekering vaak een periode direct na ingang waarin werkloosheid niet is gedekt?", [["Om te voorkomen dat iemand zich verzekert terwijl hij al weet dat hij werkloos wordt", "Deze periode beschermt de verzekeraar tegen antiselectie: verzekeren als het risico al voorzienbaar is."], ["Omdat de WW in die eerste periode het volledige inkomen al vervangt", "De WW vervangt nooit het volledige inkomen; daar is deze regel niet voor."], ["Omdat de premie in die periode fiscaal aftrekbaar is", "De premie van een woonlastenverzekering is niet aftrekbaar."], ["Omdat de wet verbiedt werkloosheid direct vanaf de ingangsdatum van de polis te verzekeren", "Er bestaat geen wettelijk verbod; het is een keuze van de verzekeraar."]], "1g.12"],
["Een werkgever biedt een collectieve WGA-hiaatverzekering aan waarvoor werknemers een premiebijdrage betalen. Werknemer Daphne wil niet meedoen en tekent een afstandsverklaring. Wat is het gevolg?", [["Zij heeft geen dekking en de werkgever legt vast dat zij bewust van de verzekering afziet", "Een afstandsverklaring laat zien dat de werknemer is geïnformeerd en zelf heeft gekozen. Bij arbeidsongeschiktheid kan zij geen aanspraak maken op de collectieve dekking."], ["Zij blijft toch verzekerd, maar betaalt geen premie", "Wie afstand doet, valt buiten de dekking; anders zou meedoen zonder bijdrage mogelijk zijn."], ["De werkgever moet haar premie dan volledig zelf betalen", "De afstandsverklaring betekent juist dat er voor haar geen premie en geen dekking is."], ["Zij krijgt bij arbeidsongeschiktheid een hogere WGA-uitkering van het UWV", "De WGA-uitkering van het UWV verandert niet door het afzien van een private aanvulling."]], "1h.9"],
["Hoe worden een WW- en een WIA-uitkering fiscaal behandeld?", [["Als belast inkomen in box 1; het UWV houdt loonheffing in", "Uitkeringen van het UWV zijn belast als inkomen; het UWV houdt loonheffing in, net als een werkgever."], ["Als onbelast vervangend inkomen", "Vervangend inkomen uit werknemersverzekeringen is juist belast."], ["Als inkomen in box 2, omdat het een uitkering van de overheid is", "Box 2 is voor inkomen uit aanmerkelijk belang, niet voor uitkeringen."], ["Belast in box 1, maar zonder inhouding; de ontvanger betaalt via de aangifte", "Het UWV houdt wel loonheffing in op de uitkering."]], "1i.5"],
["Een zelfstandige betaalt de vervolgpremie van zijn AOV niet op tijd. Wanneer mag de verzekeraar de dekking in beginsel schorsen?", [["Pas na een aanmaning en een ongebruikt verstreken termijn van 14 dagen", "Bij een niet-betaalde vervolgpremie moet de verzekeraar eerst aanmanen; pas als de betaaltermijn van 14 dagen ongebruikt verstrijkt, kan hij de dekking schorsen. De premie blijft verschuldigd."], ["Direct op de dag na de vervaldatum, zonder aanmaning", "Voor een vervolgpremie geldt de eis van een aanmaning met een betaaltermijn."], ["Pas na een jaar premieachterstand", "Zo lang hoeft de verzekeraar niet te wachten; na aanmaning en verstrijken van de termijn kan hij schorsen."], ["Nooit, een AOV kan niet wegens premieachterstand worden geschorst", "Ook een AOV kan bij premieachterstand na aanmaning worden geschorst."]], "1j.1"],
["Welk inkomen is het meest relevant om te beoordelen of een klant zijn woonlasten kan blijven dragen na arbeidsongeschiktheid?", [["Het netto besteedbare inkomen na belastingen en premies", "De vaste lasten worden betaald uit wat netto overblijft; daarom vergelijkt de adviseur het netto inkomen vóór en na het risico."], ["Het bruto jaarinkomen inclusief vakantiegeld", "Een bruto bedrag zegt niet hoeveel er werkelijk te besteden is."], ["Het toetsinkomen dat de geldverstrekker voor de hypotheek gebruikte", "Het toetsinkomen bepaalt de maximale hypotheek, niet wat er na een risico overblijft."], ["Het belastbaar inkomen in box 1 uit de laatste aangifte", "Het belastbaar inkomen is fiscaal en zegt weinig over het besteedbare inkomen."]], "1d.2"],
["Kim (33) is leerkracht en verdient € 3.400 bruto per maand; haar partner Ruben (35) is zelfstandig elektricien met € 45.000 winst per jaar. Zij hebben net een huis gekocht met een hypotheek die alleen op basis van hun twee inkomens haalbaar was. Volgend jaar verwachten zij hun eerste kind. Hun adviseur maakt een inkomensanalyse voor ziekte, arbeidsongeschiktheid, werkloosheid en overlijden. Wat is het belangrijkste aandachtspunt in die analyse?", [["Het wegvallen van één van beide inkomens kan de woonlasten direct onbetaalbaar maken", "Als de financiering op twee inkomens rust, is elk risico van elke partner relevant voor de betaalbaarheid."], ["Alleen het risico van de hoogste verdiener hoeft te worden geanalyseerd", "Ook het wegvallen van het laagste inkomen kan bij een krappe financiering problemen geven."], ["Het risico is klein, omdat twee inkomens elkaar bij het wegvallen van één inkomen automatisch compenseren", "Een inkomen dat wegvalt, wordt niet vanzelf door het andere opgevangen."], ["Alleen het pensioenrisico is relevant, omdat beide partners werken", "Arbeidsongeschiktheid, werkloosheid en overlijden blijven ook bij tweeverdieners relevant."]], "1d.2"],
["Ronald (46) is zelfstandig vertaler en maakt € 42.000 winst per jaar. Hij is getrouwd en heeft twee kinderen; zijn vrouw heeft geen betaald werk. Uit de inkomensanalyse blijkt een groot inkomensgat bij arbeidsongeschiktheid. Ronald vindt de AOV-premie te hoog en wil het risico zelf dragen. Wat doet de adviseur?", [["De risico's en gevolgen uitleggen en de keuze van de klant aantoonbaar vastleggen", "De klant mag zelf kiezen, maar de adviseur moet laten zien dat hij het risico duidelijk heeft gemaakt en de keuze documenteren."], ["Het advies weigeren, omdat de klant het risico niet wil afdekken met een verzekering", "Een klant mag een risico zelf dragen; weigeren is niet nodig als het risico is uitgelegd."], ["De AOV toch afsluiten, omdat die passend is", "Zonder instemming van de klant mag de adviseur geen verzekering sluiten."], ["Niets vastleggen, omdat er geen product is verkocht", "Juist een afwijzing van een advies moet worden vastgelegd in het dossier."]], "2e.1"],
["Hoe verloopt het inkomen van een werknemer bij langdurige arbeidsongeschiktheid op hoofdlijnen?", [["Eerst loondoorbetaling tot twee jaar, daarna de WIA met eerst een loongerelateerde fase", "De inkomensanalyse volgt deze fasen: werkgever, dan UWV met loongerelateerde WGA of IVA, en eventueel daarna de WGA-vervolgfase."], ["Direct een WIA-uitkering vanaf de eerste ziektedag", "In de eerste twee jaar betaalt de werkgever het loon door; de WIA volgt daarna."], ["Eerst een jaar ZW, daarna een jaar loondoorbetaling", "Voor een werknemer in dienst geldt eerst loondoorbetaling door de werkgever, niet de ZW."], ["Twee jaar loondoorbetaling, daarna altijd een IVA tot de AOW-leeftijd", "Of het een IVA of WGA wordt, hangt af van mate en duurzaamheid van de arbeidsongeschiktheid."]], "1i.1"],
["Hoe bepaalt een adviseur het te verzekeren inkomen van een zelfstandige met wisselende winsten?", [["Op basis van een gemiddelde over meerdere jaren en de verwachte ontwikkeling", "Een gemiddelde voorkomt dat een uitzonderlijk goed of slecht jaar het advies vertekent."], ["Op basis van het hoogste jaar, zodat hij in een goed jaar nooit te weinig verzekerd is", "Uitgaan van het beste jaar kan leiden tot oververzekering die de verzekeraar niet accepteert."], ["Op basis van de omzet, omdat die het hele inkomen weergeeft", "Omzet is geen inkomen; de kosten moeten eerst worden afgetrokken."], ["Op basis van het laatste kwartaal, omdat dat het meest actueel is", "Een kwartaal is te kort om een betrouwbaar beeld van het inkomen te geven."]], "1e.1"],
["Waar vindt een adviseur informatie over aanvullende voorzieningen van een werknemer bij arbeidsongeschiktheid of overlijden?", [["In de arbeidsvoorwaarden, de cao, het pensioenreglement en het UPO", "Werkgevers regelen aanvullingen vaak in cao of pensioenreglement; die bronnen laten zien welke dekking de klant al heeft."], ["Alleen in de loonstrook van de laatste maand", "Een loonstrook toont inhoudingen, maar niet de voorwaarden van de regelingen."], ["In het Kadaster, waar alle verzekeringen geregistreerd staan", "Het Kadaster registreert onroerend goed, geen verzekeringen."], ["Bij het UWV, dat alle particuliere polissen registreert", "Het UWV houdt geen overzicht bij van particuliere of werkgeversverzekeringen."]], "1b.7"],
["Waarom betrekt een adviseur bij een inkomensanalyse ook de partner van de klant?", [["Het huishouden draagt de lasten samen en het partnerinkomen beïnvloedt uitkeringen", "Inkomensrisico's raken het hele huishouden, en regelingen als de Toeslagenwet en de bijstand houden rekening met het partnerinkomen."], ["Omdat de partner wettelijk medeaansprakelijk is voor de premie van een AOV", "Er is geen wettelijke aansprakelijkheid van de partner voor de premie."], ["Omdat de partner altijd medeverzekerde moet zijn op elke polis", "Er is geen plicht om de partner op elke polis mee te verzekeren."], ["Omdat de WIA-uitkering afhangt van het vermogen van de partner", "De WIA kent geen vermogens- of partnertoets."]], "1d.2"],
["Bert (41) is logistiek manager en verdient € 4.600 bruto per maand. Hij is getrouwd en heeft twee jonge kinderen; zijn vrouw werkt parttime. Bij zijn huidige werkgever is het nabestaandenpensioen op risicobasis verzekerd. Hij stapt over naar een andere werkgever met een andere pensioenregeling. Welk overlijdensrisico verdient extra aandacht?", [["Zijn nabestaandenpensioen op risicobasis kan bij uitdiensttreding vervallen", "Op risicobasis verzekerd nabestaandenpensioen wordt niet opgebouwd; na uitdiensttreding (en een eventuele korte uitloopperiode) kan het vervallen, terwijl de nieuwe regeling minder kan dekken."], ["Zijn Anw-recht vervalt zodra hij bij een nieuwe werkgever met een ander pensioenfonds in dienst treedt", "De Anw is een volksverzekering en staat los van de werkgever."], ["Zijn ORV vervalt automatisch bij baanwissel", "Een particuliere ORV is niet gekoppeld aan het dienstverband."], ["Zijn AOW-opbouw stopt tijdelijk tijdens de overgang", "De AOW-opbouw hangt af van wonen of werken in Nederland, niet van de werkgever."]], "1d.2"],
["Casus: een medewerker van adviseur Noor verliest een onversleutelde laptop met klantdossiers. Binnen welke termijn moet het kantoor dit datalek in de regel melden bij de Autoriteit Persoonsgegevens?", [["Binnen 72 uur na ontdekking", "De AVG vraagt een melding zonder onredelijke vertraging en zo mogelijk binnen 72 uur nadat het lek is ontdekt."], ["Binnen vier weken, na intern onderzoek", "Vier weken is veel te lang; de AVG noemt 72 uur."], ["Binnen een jaar, in het jaarverslag", "Een melding achteraf in een jaarverslag voldoet niet aan de AVG."], ["Alleen als de klant daar zelf om vraagt", "De meldplicht geldt los van een verzoek van de klant."]], "1a.6"],
["Een werkgever heeft al jaren een collectieve verzuimverzekering. Door een paar langdurig zieke werknemers is de schadelast de laatste jaren sterk gestegen. Wat mag hij bij de verlenging verwachten?", [["De verzekeraar kan de premie verhogen of de voorwaarden aanscherpen", "Collectieve contracten worden vaak geprijsd op het eigen schadeverloop. Bij een hoge schadelast volgt bij verlenging vaak een hogere premie of bijvoorbeeld een langere eigenrisicoperiode."], ["De premie daalt, omdat de verzekeraar al veel heeft uitgekeerd", "Een hoge schadelast leidt juist tot een hogere premie."], ["Niets, want de premie van een verzuimverzekering staat wettelijk vast", "Er is geen wettelijke premie; de verzekeraar bepaalt de premie zelf."], ["Het UWV neemt de verzekering over vanwege het hoge verzuim", "Het UWV neemt geen particuliere verzuimverzekeringen over."]], "1j.4"],
["Casus: een adviseurskantoor bewaart klantdossiers in een cloudpakket van een externe leverancier. Wat moet het kantoor in elk geval regelen?", [["Een verwerkersovereenkomst met de leverancier", "Een externe partij die persoonsgegevens verwerkt voor het kantoor is verwerker; de AVG vraagt dan een verwerkersovereenkomst."], ["Toestemming van elke klant voor gebruik van dat cloudpakket", "Niet toestemming, maar een verwerkersovereenkomst is hier de vereiste waarborg."], ["Een vergunning van de AFM voor gegevensopslag", "De AFM verleent geen vergunningen voor gegevensopslag."], ["Een melding bij het Kifid", "Het Kifid behandelt klachten en heeft geen rol bij gegevensverwerking."]], "1a.6"],
["Anke en Rob drijven samen een cateringbedrijf in de vorm van een vennootschap onder firma (vof). Wat geldt voor hun aansprakelijkheid voor de schulden van de vof?", [["Elke vennoot is hoofdelijk aansprakelijk, ook met zijn privévermogen", "In een vof kunnen schuldeisers elke vennoot voor het geheel aanspreken, ook in privé. Dat maakt inkomensbescherming extra belangrijk."], ["Alleen het vermogen van de vof kan worden aangesproken, zoals bij een bv", "Een vof is geen rechtspersoon; de vennoten zijn ook privé aansprakelijk."], ["Elke vennoot is alleen aansprakelijk voor de helft van de schulden", "Vennoten zijn hoofdelijk aansprakelijk, dus elk voor het geheel."], ["Alleen de vennoot die de schuld is aangegaan, is aansprakelijk", "Bij een vof zijn alle vennoten aansprakelijk voor de verbintenissen van de vof."]], "1c.1"],
["Welke vorm van toestemming is nodig als een verwerking van gezondheidsgegevens op toestemming wordt gebaseerd?", [["Uitdrukkelijke toestemming voor dat specifieke doel", "Voor bijzondere persoonsgegevens geldt een strengere eis: de toestemming moet uitdrukkelijk zijn."], ["Stilzwijgende toestemming door het accepteren van de offerte", "Stilzwijgen of een vooraf aangevinkt vakje is geen geldige toestemming, zeker niet voor gezondheidsgegevens."], ["Mondelinge toestemming van de partner", "Toestemming moet komen van de betrokkene zelf, niet van een ander."], ["Algemene toestemming in de algemene voorwaarden", "Een verwijzing in algemene voorwaarden is niet specifiek en uitdrukkelijk genoeg."]], "1a.6"],
["Casus: tijdens een AOV-gesprek vertelt een klant spontaan uitgebreid over een recente diagnose. Wat is de juiste houding van de adviseur?", [["Alleen vastleggen wat nodig is en wijzen op de gezondheidsverklaring", "Dataminimalisatie betekent geen medische details opslaan die de adviseur niet nodig heeft; de verklaring gaat rechtstreeks naar de medisch adviseur."], ["De diagnose volledig in het klantdossier opnemen, zodat die later bij de aanvraag te gebruiken is", "Gezondheidsgegevens zijn bijzonder; onnodig vastleggen is in strijd met de AVG."], ["De diagnose direct per e-mail aan de verzekeraar doorsturen", "Medische informatie gaat via de gezondheidsverklaring naar de medisch adviseur, niet via de adviseur."], ["Het gesprek beëindigen, omdat hij deze informatie niet mag horen", "Het horen is niet verboden; het gaat om het zorgvuldig omgaan ermee."]], "4b.2"],
["Wat is de rol van de medisch adviseur van een verzekeraar bij de acceptatie van een AOV?", [["Hij beoordeelt de medische informatie onder beroepsgeheim en adviseert de acceptant", "De acceptant krijgt alleen het advies, zoals een uitsluiting of opslag, en geen medische details."], ["Hij neemt namens de adviseur de gezondheidsverklaring met de klant door en vult die zo nodig aan", "De medisch adviseur werkt voor de verzekeraar en niet namens de adviseur."], ["Hij deelt de diagnose met de adviseur zodat die beter kan adviseren", "Medische details blijven bij de medisch adviseur onder zijn beroepsgeheim."], ["Hij stelt het arbeidsongeschiktheidspercentage voor de WIA vast", "Dat doet het UWV, niet de medisch adviseur van een particuliere verzekeraar."]], "1h.2"],
["Casus: hypotheekadviseur Ruud wil zijn klanten ook adviseren over een particuliere AOV. Welk diploma heeft hij daarvoor naast Wft Basis in elk geval nodig?", [["Wft Inkomen", "Advies over inkomensverzekeringen zoals de AOV valt onder de module Wft Inkomen."], ["Wft Schadeverzekeringen Particulier", "Die module betreft schadeverzekeringen zoals inboedel en aansprakelijkheid, niet de AOV."], ["Wft Vermogen", "Wft Vermogen gaat over vermogensopbouw, niet over inkomensverzekeringen."], ["Wft Pensioen", "Wft Pensioen betreft pensioenregelingen, niet de particuliere AOV."]], "4b.3"],
["Fleur (36) is zelfstandig kapper met een eigen salon en maakt € 35.000 winst per jaar. Zij woont samen en heeft een dochter van drie. Na een polsoperatie kan zij maanden niet knippen, maar de verzekeraar wijst haar AOV-claim af. Fleur is het daar niet mee eens en heeft de interne klachtenprocedure van de verzekeraar al doorlopen. Waar kan zij dan terecht?", [["Bij het Kifid of de burgerlijke rechter", "Na de interne klachtenprocedure kan Fleur het geschil met de verzekeraar voorleggen aan het Kifid of aan de rechter."], ["Bij het UWV, dat AOV-claims toetst", "Het UWV toetst publieke uitkeringen en heeft geen rol bij particuliere polissen."], ["Bij de AFM, die het individuele geschil beslecht", "De AFM houdt toezicht op het gedrag van financiële ondernemingen, maar beslecht geen individuele geschillen."], ["Bij de Autoriteit Persoonsgegevens", "De AP gaat over de bescherming van persoonsgegevens, niet over de beoordeling van een claim."]], "1a.3"],
["Hoe mag een adviseur worden beloond voor zijn advies over een particuliere AOV?", [["Rechtstreeks door de klant, omdat het provisieverbod van toepassing is", "Voor onder meer de AOV geldt een provisieverbod: de adviseur mag geen provisie van de verzekeraar ontvangen."], ["Met provisie van de verzekeraar, mits hij die vooraf meldt", "Melding maakt provisie niet toegestaan; voor de AOV geldt een verbod."], ["Alleen met een vaste vergoeding van de verzekeraar per polis", "Ook een vaste vergoeding van de verzekeraar valt onder het provisieverbod."], ["Met een bonus van de verzekeraar bij een hoge premie", "Zo'n prikkel strijdt met het provisieverbod en met het klantbelang."]], "1h.5"],
["Naomi (38) is apothekersassistente en verdient € 1.900 bruto per maand voor drie dagen werk. Haar partner overlijdt aan kanker en zij zorgt nu alleen voor hun dochter van zes. Zij krijgt een nabestaandenpensioen van het pensioenfonds van haar partner. Daarnaast vraagt zij een Anw-uitkering aan. Wordt dat nabestaandenpensioen verrekend met haar Anw-uitkering?", [["Nee, een nabestaandenpensioen is geen inkomen uit arbeid en wordt niet verrekend", "De Anw verrekent alleen inkomen uit of in verband met arbeid; een nabestaandenpensioen valt daar niet onder."], ["Ja, het nabestaandenpensioen wordt volledig met de Anw verrekend", "Volledige verrekening vindt niet plaats; het nabestaandenpensioen telt voor de Anw niet mee."], ["Ja, voor 70% zoals bij inkomen uit een baan", "De gedeeltelijke verrekening geldt voor arbeidsinkomen, niet voor een nabestaandenpensioen."], ["Alleen als het pensioen hoger is dan de Anw-uitkering zelf", "Er bestaat geen drempel waarboven een nabestaandenpensioen alsnog wordt verrekend."]], "1i.2"]
];
